const T40_VENTILACION_175=Object.freeze({
  '18':Object.freeze({page:130,ratios:['0,5','1','1,5'],values:[90,71,50]}),
  '20':Object.freeze({page:141,ratios:['0,5','1','1,5','2','3','4'],values:[50,71,83,89,95,97]}),
  '22':Object.freeze({page:142,ratios:['0,5','1','1,5','2','3','4'],values:[80,50,30,20,10,6]})
});
const T40_R_175=Object.freeze([
  {tipo:'ventilación natural vertical',rec:'r < 0,5',min:'r < 1'},
  {tipo:'VPP ofensiva',rec:'r > 2',min:'r > 1'},
  {tipo:'VPP defensiva',rec:'r > 2',min:'r > 0,5'}
]);
function t40TablaFact175(t){
  if(Number(t?.topic_id)!==50||!t?.exam_relevant)return null;
  const m=String(t.concept||'').match(/^T40-T(18|20|21|22)-K00([1-9])\s*\|/);
  if(!m)return null;
  const table=m[1],idx=Number(m[2])-1;
  const evidence=String(t.source_evidence||'').replace(/\\u003c/gi,'<')
    .replace(/\\u003e/gi,'>').replace(/\s+/g,' ').trim();
  const compact=evidence.toLowerCase().replace(/\s+/g,'');
  if(!Number.isInteger(Number(t.source_page))||
     !evidence.includes(`T40-T${table}-K${String(idx+1).padStart(3,'0')}`))return null;
  if(table==='21'){
    const f=T40_R_175[idx];
    if(!f||Number(t.manual_page)!==142)return null;
    if(!compact.includes(`recomendable:${f.rec.toLowerCase().replace(/\s+/g,'')}`)||
       !compact.includes(`mínimo:${f.min.toLowerCase().replace(/\s+/g,'')}`))return null;
    return {table,idx,rec:f.rec,min:f.min,tipo:f.tipo};
  }
  const f=T40_VENTILACION_175[table];
  if(!f||idx<0||idx>=f.values.length||Number(t.manual_page)!==f.page)return null;
  const r=f.ratios[idx],value=f.values[idx];
  if(!compact.includes(`r=${r}`)||
     !new RegExp(`(?:^|[^0-9])${value}\\s*%`).test(evidence))return null;
  if(table==='18'&&!/ventilación natural vertical/i.test(evidence))return null;
  if(table==='20'&&!/rendimiento/i.test(evidence))return null;
  if(table==='22'&&!/presión diferencial/i.test(evidence))return null;
  return {table,idx,r,value};
}
function t40TablaPregunta175(t,seed=0,difficulty='alta'){
  const fact=t40TablaFact175(t);
  if(!fact)return null;
  const sourceEvidence=String(t.source_evidence);
  const page=String(t.manual_page);
  let stem,opts,correct;
  if(fact.table==='21'){
    // Cuatro relaciones del MISMO tipo, no opciones absurdas de otras técnicas.
    const requested=seed%2===0?'rec':'min';
    correct=fact[requested];
    stem=`Para la ${fact.tipo}, con r = área de salida de gases / área de entrada de aire, ¿qué condición ${requested==='rec'?'recomendable':'mínima'} establece el manual para esa relación de áreas?`;
    const candidateValues=['r < 0,5','r < 1','r > 0,5','r > 1','r > 2'];
    opts=[correct,...candidateValues.filter(x=>x!==correct).slice((fact.idx+seed)%2,(fact.idx+seed)%2+3)];
    if(opts.length!==4)opts=[correct,...candidateValues.filter(x=>x!==correct).slice(0,3)];
  }else{
    const f=T40_VENTILACION_175[fact.table],v=f.values,idx=fact.idx;
    if(fact.table==='18'){
      stem=`En ventilación natural vertical de gases a 500 °C, la relación entre área de salida y entrada es r = ${fact.r}. ¿Qué rendimiento sobre el teórico máximo corresponde a esa condición?`;
      opts=[`${fact.value} %`,...([90,71,50,80].filter(x=>x!==fact.value).map(x=>`${x} %`)).slice(0,3)];
    }else if(fact.table==='20'){
      stem=`En una ventilación por presión positiva (VPP) destinada a evacuar gases, la relación área de salida / área de entrada es r = ${fact.r}. ¿Qué porcentaje del caudal efectivo máximo teórico se alcanza?`;
      const order=[...v.keys()].filter(i=>i!==idx).sort((a,b)=>Math.abs(a-idx)-Math.abs(b-idx));
      opts=[`${fact.value} %`,...order.slice(0,3).map(i=>`${v[i]} %`)];
    }else{
      stem=`Durante una operación de presurización con VPP, la relación entre el área de salida y la de entrada de gases es r = ${fact.r}. ¿Qué porcentaje del diferencial de presión máximo teórico corresponde?`;
      const order=[...v.keys()].filter(i=>i!==idx).sort((a,b)=>Math.abs(a-idx)-Math.abs(b-idx));
      opts=[`${fact.value} %`,...order.slice(0,3).map(i=>`${v[i]} %`)];
    }
    correct=`${fact.value} %`;
  }
  const evidenceSuffix=fact.table==='21'
    ?`${fact.tipo}: recomendable ${fact.rec}; mínima ${fact.min}.`
    :`r=${fact.r}, ${fact.table==='22'?'diferencial de presión':'rendimiento'} ${fact.value} %.`;
  const q={stem,options:opts,correctIndex:0,
    explanation:`Según el manual CEIS Guadalajara, tabla ${fact.table}, página ${page}: ${evidenceSuffix}`,
    sourceEvidence,sourcePage:t.source_page,manualPage:page,
    questionFamily:'2026_CORRECTA',difficulty,resetLocal136:true,t40Tabla175:fact.table};
  return resetShape136(q)?null:q;
}

function t40FormulaQr175(t,difficulty='alta'){
  if(Number(t?.topic_id)!==50||Number(t?.id)!==24035||
     Number(t?.manual_page)!==141||!t?.exam_relevant)return null;
  const evidence=String(t.source_evidence||'');
  if(!evidence.includes('Qr = k x (r / raíz de (1 + r²))')||
     !evidence.includes('r = Ae / Ai'))return null;
  // Los delimitadores \(...\) son compatibles con el KaTeX ya cargado en
  // public/app.js. Las CUATRO expresiones se muestran como fracción apilada.
  const options=[
    String.raw`\(\displaystyle Q_r=k\cdot\frac{r}{\sqrt{1+r^2}}\)`,
    String.raw`\(\displaystyle Q_r=k\cdot\frac{r^2}{\sqrt{1+r^2}}\)`,
    String.raw`\(\displaystyle Q_r=k\cdot\frac{r}{\sqrt{1+r}}\)`,
    String.raw`\(\displaystyle Q_r=k\cdot\frac{r}{\sqrt{1+2r^2}}\)`
  ];
  const q={
    stem:'En ventilación por presión positiva (VPP), el caudal efectivo (Qr) creado por un ventilador depende de la relación entre el área de salida de gases (Ae) y el área de entrada (Ai). Con r = Ae/Ai y k como la constante de la ecuación, ¿qué expresión reproduce el caudal efectivo, sin considerar el efecto del incendio?',
    options,correctIndex:0,
    explanation:'Manual CEIS Guadalajara, página 141: el caudal efectivo de la VPP depende de r=Ae/Ai y sigue Qr=k·r/√(1+r²).',
    sourceEvidence:evidence,sourcePage:t.source_page,manualPage:String(t.manual_page),
    questionFamily:'2026_CORRECTA',difficulty,resetLocal136:true,t40Formula175:true
  };
  return resetShape136(q)?null:q;
}

// Dentro del selector EXISTENTE, sin tocar fechas SRS ni hacer una nueva SQL.
// Se reemplazan SOLO plazas del mismo nivel de prioridad y mismo tema.
// Cada test corto de T40 reserva hasta dos relaciones tabuladas verificadas.
function t40PriorizarTablas175(selected,candidates,count,topicIds,strategy){
  if(!Array.isArray(topicIds)||topicIds.length!==1||Number(topicIds[0])!==50||
     strategy==='simulation'||count<5)return;
  const target=Math.min(3,Math.max(1,Math.floor(count/5)));
  const current=new Set(selected.filter(t=>t40TablaFact175(t)).map(t=>t40TablaFact175(t).table));
  const selectedIds=new Set(selected.map(t=>Number(t.id)));
  const pool=candidates.filter(t=>!selectedIds.has(Number(t.id))&&t40TablaFact175(t));
  // Tablas distintas primero; dentro de ellas, la ficha de menor exposición.
  pool.sort((a,b)=>(Number(a.adaptive_priority||4)-Number(b.adaptive_priority||4))||
    (Number(a.times_asked||0)-Number(b.times_asked||0))||Number(a.id)-Number(b.id));
  let replaced=0;
  for(const candidate of pool){
    if(current.size>=target)break;
    const group=t40TablaFact175(candidate).table;
    if(current.has(group))continue;
    const slot=selected.findIndex((t,i)=>i>0&&i%10!==8&&
      !t40TablaFact175(t)&&Number(t.adaptive_priority||4)===Number(candidate.adaptive_priority||4));
    if(slot<0)continue;
    selectedIds.delete(Number(selected[slot].id));
    selected[slot]=candidate;selectedIds.add(Number(candidate.id));
    current.add(group);replaced++;
  }
  if(replaced)console.log('T40_175_TABLAS_PRIORIZADAS',JSON.stringify({count,replaced,groups:[...current]}));
}

// SERVER176: solución del ejercicio CEIS p.115 con MAGNITUD correcta.
// El manual imprime "30,3L de vapor de agua", pero calcula 30,3 L de AGUA
// LÍQUIDA para producir 62.500 L de vapor. Se conserva la cita literal en
// sourceEvidence; no se altera el PDF, historial SRS ni la base de datos.
function t40AguaLiquida176(t,difficulty='muy alta'){
  if(Number(t?.topic_id)!==50||Number(t?.id)!==23905||
     Number(t?.manual_page)!==115||!t?.exam_relevant)return null;
  const evidence=String(t.source_evidence||'');
  if(!/5\s*x\s*5\s*m/i.test(evidence)||
     !evidence.includes('30,3L de vapor de agua'))return null;
  const q={
    stem:'En un recinto confinado de 5 m × 5 m de planta y 2,5 m de altura, se pretende llenarlo de vapor a 200 °C. Si 1 L de agua líquida produce 2.060 L de vapor a esa temperatura y la efectividad es del 100 %, ¿qué volumen de AGUA LÍQUIDA es necesario?',
    options:['15,2 L de agua líquida','30,3 L de agua líquida',
      '62,5 L de agua líquida','125,0 L de agua líquida'],
    correctIndex:1,
    explanation:String.raw`El recinto contiene \(5\cdot5\cdot2{,}5=62{,}5\ \mathrm{m}^3=62\,500\ \mathrm{L}\) de volumen. El agua líquida necesaria es \(V_{agua}=\frac{62\,500}{2\,060}=30{,}34\ \mathrm{L}\), aproximadamente 30,3 L. NOTA DOCUMENTAL: la respuesta impresa del CEIS, p. 115, dice «30,3 L de vapor de agua», pero ese volumen corresponde al agua LÍQUIDA antes de evaporarse; el vapor ocupa 62.500 L.`,
    sourceEvidence:evidence,sourcePage:t.source_page,manualPage:'115',
    questionFamily:'CALCULO_FORMULACION',difficulty,resetLocal136:true,t40Liquid176:true
  };
  return resetShape136(q)?null:q;
}

// SERVER159: el esquema existente puede conservar un CHECK heredado (0..2),
// aunque el DDL actual permite 0..3. Sin corregirlo, 10 de las 45 preguntas
// T40 con respuesta D fracasarían y se revertiría toda la importación.
// Migración puntual y transaccional, sólo al importar T40; no cambia opciones.
async function t40EnsureFourOptions159(){
  const client=await db.connect();
  try{
    await client.query('BEGIN');
    const c=await client.query(`SELECT pg_get_constraintdef(oid) AS definition
      FROM pg_constraint
      WHERE conrelid='question_bank'::regclass
        AND conname='question_bank_correct_index_check' AND contype='c'
      LIMIT 1`);
    const definition=String(c.rows[0]?.definition||'');
    if(!definition)throw Error('T40: no se ha encontrado la restricción de índice de respuesta.');
    if(/correct_index\s*<\s*3\b/.test(definition)){
      await client.query(`ALTER TABLE question_bank
        DROP CONSTRAINT question_bank_correct_index_check`);
      await client.query(`ALTER TABLE question_bank
        ADD CONSTRAINT question_bank_correct_index_check
        CHECK (correct_index BETWEEN 0 AND 3)`);
      console.log('T40_159_CHECK_INDICE_RESPUESTA_0_A_3_CORREGIDO');
    }
    await client.query('COMMIT');
  }catch(error){
    await client.query('ROLLBACK');
    throw error;
  }finally{client.release();}
}
async function t40ImportOnce157(topic){
  if(!t40Topic157(topic))return {skipped:true};
  const pack=t40Resources157Load();
  if(!pack)throw Error('T40: falta t40_graphics_data.js.');
  t40WriteImages157();
  await t40EnsureFourOptions159();
  const client=await db.connect();
  try{
    await client.query('BEGIN');
    const locked=await client.query(
      'SELECT id,name,block,total_items,file_search_indexed FROM topics WHERE id=$1 FOR UPDATE',
      [Number(topic.id)]);
    const t=locked.rows[0];
    const source=await client.query(`SELECT 1 FROM topic_local_pdfs
      WHERE topic_id=$1 AND TRIM(pdf_sha256)=$2 AND page_count=66
        AND size_bytes=OCTET_LENGTH(pdf_bytes) LIMIT 1`,
      [Number(topic.id),pack.pdf_sha256]);
    if(!t40Topic157(t)||Number(t.total_items)<1||
       (!t.file_search_indexed && !source.rows.length))
      throw Error('T40: antes hay que cargar el PDF y confirmar la cobertura.');
    let installed=0;
    const seen=new Set();
    for(const row of pack.questions){
      const name=String(row.graphic?.publicUrl||'').split('/').pop();
      const bytes=pack.images.find(im=>im.file===name);
      if(!bytes||bytes.sha256!==row.graphic_image_source_sha256||
         !Number.isInteger(row.correct_index)||row.correct_index<0||row.correct_index>3||
         !Array.isArray(row.options)||row.options.length!==4||
         new Set(row.options).size!==4||row.question_family!=='GRAFICA'||
         row.difficulty!=='muy alta'||row.source_page<1||row.source_page>66||
         !/^T40-GRAF-\d{5}$/.test(row.external_key))
        throw Error('T40: pregunta o imagen inválida: '+row.external_key);
      const key=row.external_key;
      if(seen.has(key))throw Error('T40: pregunta repetida: '+key);
      seen.add(key);
      const uri='/graphics/incendios-interior/'+name;
      const sourceId='incendios-interior/'+name;
      const picture=await client.query(`
        INSERT INTO graphic_assets(source_id,topic_folder,source_file,public_url,
          asset_index,asset_type,concept,description,source_evidence,crop_x,crop_y,
          crop_width,crop_height,mask_regions,is_official_reference,is_usable,
          analysis_status,sanitization_version)
        VALUES($1,'incendios-interior',$2,$3,0,'individual',$4,$5,$6,
          0,0,1,1,'[]'::jsonb,FALSE,TRUE,'analyzed',2)
        ON CONFLICT(source_id,asset_index) DO UPDATE SET
          concept=EXCLUDED.concept,description=EXCLUDED.description,
          source_evidence=EXCLUDED.source_evidence,public_url=EXCLUDED.public_url,
          crop_x=0,crop_y=0,crop_width=1,crop_height=1,mask_regions='[]'::jsonb,
          is_usable=TRUE,analysis_status='analyzed',sanitization_version=2,
          updated_at=NOW()
        RETURNING id`,[sourceId,name,uri,row.coverage_concept,
          `Figura ${Number(name.match(/_FIG_(\d+)_/)?.[1])}, página CEIS ${row.manual_page}; esquema sin pie editorial`,
          row.source_evidence]);
      const assetId=Number(picture.rows[0].id);
      const concept=key+' · '+row.coverage_concept;
      const target=await client.query(`
        INSERT INTO coverage_items(topic_id,section,concept,item_type,evaluation_type,
          source_page,manual_page,source_evidence,exam_relevant)
        VALUES($1,$2,$3,'grafica_t40_original','interpretacion_visual',$4,$5,$6,TRUE)
        ON CONFLICT(topic_id,concept,item_type,evaluation_type) DO UPDATE SET
          exam_relevant=TRUE,section=EXCLUDED.section,
          source_page=EXCLUDED.source_page,manual_page=EXCLUDED.manual_page,
          source_evidence=EXCLUDED.source_evidence
        RETURNING id`,[Number(topic.id),row.coverage_section,concept,
          row.source_page,row.manual_page,row.source_evidence]);
      const coverageId=Number(target.rows[0].id);
      const graphic={...row.graphic,assetId,publicUrl:uri,
        sourceId,assetType:'individual',concept:row.coverage_concept,
        crop:{x:0,y:0,width:1,height:1},maskRegions:[]};
      const existing=await client.query(`SELECT id,stem,options,correct_index FROM question_bank
         WHERE coverage_item_id=$1 AND question_family='GRAFICA' ORDER BY id DESC
         LIMIT 1 FOR UPDATE`,[coverageId]);
      if(existing.rows.length){
        const prev=existing.rows[0];
        if(String(prev.stem)!==String(row.stem)||
           JSON.stringify(prev.options)!==JSON.stringify(row.options)||
           Number(prev.correct_index)!==Number(row.correct_index))
          throw Error('T40: pregunta ya existente distinta. No se sobrescribe '+key);
        await client.query(`UPDATE question_bank SET active=TRUE,graphic=$2::jsonb,
          updated_at=NOW() WHERE id=$1`,[prev.id,JSON.stringify(graphic)]);
      }else{
        await client.query(`INSERT INTO question_bank(coverage_item_id,stem,options,
          correct_index,explanation,source_evidence,source_page,manual_page,
          question_family,difficulty,graphic,validation_version,active)
          VALUES($1,$2,$3::jsonb,$4,$5,$6,$7,$8,'GRAFICA','muy alta',$9::jsonb,6,TRUE)`,
          [coverageId,row.stem,JSON.stringify(row.options),row.correct_index,
           row.explanation,row.source_evidence,row.source_page,row.manual_page,
           JSON.stringify(graphic)]);
      }
      installed++;
    }
    if(installed!==45)throw Error('T40: no se han importado las 45 preguntas.');
    // Las capturas antiguas ya no se usan en este tema: sus recortes
    // v1 podían contener títulos y pies. No toca imágenes de otros temas.
    await client.query(`UPDATE graphic_assets SET is_usable=FALSE,updated_at=NOW()
      WHERE topic_folder='incendios-interior' AND source_file LIKE 'Screenshot_%'
        AND is_usable=TRUE`);
    await client.query(`UPDATE topics SET total_items=(SELECT COUNT(*) FROM
       coverage_items WHERE topic_id=$1 AND exam_relevant=TRUE) WHERE id=$1`,
       [Number(topic.id)]);
    await client.query('COMMIT');
    console.log('T40_157_PREGUNTAS_SEMILLA',JSON.stringify({topicId:topic.id,installed}));
    return {ok:true,topicId:Number(topic.id),questions:installed,images:45,geminiCalls:0};
  }catch(e){await client.query('ROLLBACK');throw e;}
  finally{client.release();}
}

/* TEMA 41 — banco grafico cerrado sobre el PDF del CEIS, con 11 recortes
 * y 50 preguntas. Instalacion idempotente, no modifica temas anteriores.
 * Cero llamadas a Gemini para preguntas ya validadas.
 */
let t41PreparedData=null;
function t41Topic(topic){
  const name=String(topic?.name||topic?.topic_name||'').normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'').replace(/[_-]+/g,' ');
  return /^\s*tema\s*41\b/i.test(name) &&
    /incendios?\s+de\s+vegetacion/i.test(name) &&
    String(topic?.block||topic?.topic_block||'').toLowerCase()==='especifico';
}
function t41LoadData(){
  if(t41PreparedData)return t41PreparedData;
  const file=path.join(process.cwd(),'t41_graphics_data.js');
  if(!fs.existsSync(file))return null;
  const content=fs.readFileSync(file,'utf8');
  const marker='module.exports = ';
  const start=content.indexOf(marker);
  if(start<0)throw Error('T41: cabecera de paquete grafico invalida');
  const data=JSON.parse(content.slice(start+marker.length).trim().replace(/;\s*$/,''));
  if(data?.schema!==1||data.topic_number!==41||data.pdf_page_count!==36||
     !Array.isArray(data.images)||data.images.length!==11||
     !Array.isArray(data.questions)||data.questions.length!==50||
     new Set(data.images.map(x=>x.file)).size!==11||
     new Set(data.questions.map(x=>x.external_key)).size!==50)
    throw Error('T41: recortes o preguntas incompletos o repetidos');
  t41PreparedData=data;return data;
}
function t41WriteImages(){
  const data=t41LoadData();if(!data)return {skipped:true};
  const dir=path.join(process.cwd(),'public','graphics','incendios-vegetacion');
  fs.mkdirSync(dir,{recursive:true});let written=0;
  for(const asset of data.images){
    if(!/^T41_GRAF_\d{5}_FIG_\d{3}_P\d{3}\.png$/.test(asset.file))
      throw Error('T41: nombre de imagen inesperado');
    const buf=Buffer.from(asset.base64,'base64');
    const sha=createHash('sha256').update(buf).digest('hex');
    if(sha!==asset.sha256||!buf.subarray(0,8)
      .equals(Buffer.from([137,80,78,71,13,10,26,10])))
      throw Error('T41: checksum/png invalido '+asset.file);
    const dest=path.join(dir,asset.file);
    if(fs.existsSync(dest)){
      if(createHash('sha256').update(fs.readFileSync(dest)).digest('hex')!==sha)
        throw Error('T41: fichero de imagen existente distinto '+asset.file);
    }else{fs.writeFileSync(dest,buf);written++;}
  }
  return {images:11,written};
}
async function t41ImportOnce(topic){
  if(!t41Topic(topic))return {skipped:true};
  const data=t41LoadData();if(!data)return {skipped:true,missing:true};
  t41WriteImages();
  const client=await db.connect();
  try{
    await client.query('BEGIN');
    const topics=await client.query('SELECT * FROM topics WHERE id=$1 FOR UPDATE',[topic.id]);
    const t=topics.rows[0];
    // T41-179: conservar la indexación File Search existente. Su PDF no se
    // guardaba localmente, pero el banco fijo de imágenes exigía ese registro.
    // El PDF exacto (36 páginas) se incorpora en el paquete con SHA verificado.
    if(!t41Topic(t)||Number(t.total_items)<1||!t.file_search_indexed)
      throw Error('T41: tema no indexado; no se altera ninguna cobertura');
    const remote=await client.query(`SELECT document_name
      FROM topic_source_documents WHERE topic_id=$1`,[t.id]);
    if(!remote.rows[0]?.document_name)
      throw Error('T41: no hay fuente File Search vinculada; no se suplanta');
    if(!data.pdf_base64||!Array.isArray(data.coverage_additions))
      throw Error('T41: falta el PDF original y el inventario de ampliaciones');
    const pdfBytes=Buffer.from(data.pdf_base64,'base64');
    const fileHash=createHash('sha256').update(pdfBytes).digest('hex');
    if(fileHash!==data.pdf_sha256||pdfBytes.length<1000||
       pdfBytes.length>20*1024*1024||
       pdfBytes.subarray(0,5).toString('latin1')!=='%PDF-')
      throw Error('T41: PDF local distinto del original indexado');
    const source=await PDFDocument.load(pdfBytes,{updateMetadata:false});
    if(source.getPageCount()!==36)throw Error('T41: el PDF no tiene 36 páginas');
    await client.query(`INSERT INTO topic_local_pdfs
      (topic_id,pdf_sha256,page_count,size_bytes,pdf_bytes)
      VALUES($1,$2,36,$3,$4) ON CONFLICT(topic_id) DO NOTHING`,
      [t.id,fileHash,pdfBytes.length,pdfBytes]);
    const stored=await client.query(`SELECT TRIM(pdf_sha256) AS sha,
      page_count,size_bytes,OCTET_LENGTH(pdf_bytes) AS stored_size,
      encode(sha256(pdf_bytes),'hex') AS stored_sha
      FROM topic_local_pdfs WHERE topic_id=$1`,[t.id]);
    const check=stored.rows[0];
    if(!check||check.sha!==fileHash||check.stored_sha!==fileHash||
       Number(check.page_count)!==36||
       Number(check.size_bytes)!==pdfBytes.length||
       Number(check.stored_size)!==pdfBytes.length)
      throw Error('T41: copia PDF local incompatible; no se sobrescribe');
    // Completar únicamente lagunas verificadas contra páginas físicas.
    // DO NOTHING preserva historial y SRS si ya se instaló antes.
    for(const item of data.coverage_additions){
      if(!/^T41-TXT-AUD-\d{3}$/.test(item.external_key)||
         !Number.isInteger(item.source_page)||item.source_page<1||item.source_page>36||
         !item.concept||!item.source_evidence)
        throw Error('T41: ampliación documental no válida');
      await client.query(`INSERT INTO coverage_items(topic_id,section,concept,
        item_type,evaluation_type,source_page,manual_page,source_evidence,exam_relevant)
        VALUES($1,$2,$3,'concepto','literal_documental',$4,$5,$6,TRUE)
        ON CONFLICT(topic_id,concept,item_type,evaluation_type) DO NOTHING`,
        [t.id,item.section,item.external_key+' · '+item.concept,
         item.source_page,item.manual_page,item.source_evidence]);
    }
    const imgMap=new Map();
    for(const asset of data.images){
      const file=asset.file,uri='/graphics/incendios-vegetacion/'+file;
      const sourceId='incendios-vegetacion/'+file;
      const q=await client.query(`INSERT INTO graphic_assets(
        source_id,topic_folder,source_file,public_url,asset_index,asset_type,
        concept,description,source_evidence,crop_x,crop_y,crop_width,crop_height,
        mask_regions,is_official_reference,is_usable,analysis_status,sanitization_version)
        VALUES($1,'incendios-vegetacion',$2,$3,0,'individual',$4,$5,$6,
        0,0,1,1,'[]'::jsonb,FALSE,TRUE,'analyzed',2)
        ON CONFLICT(source_id,asset_index) DO UPDATE SET
        concept=EXCLUDED.concept,description=EXCLUDED.description,
        source_evidence=EXCLUDED.source_evidence,public_url=EXCLUDED.public_url,
        crop_x=0,crop_y=0,crop_width=1,crop_height=1,
        mask_regions='[]'::jsonb,is_usable=TRUE,analysis_status='analyzed',
        sanitization_version=2,updated_at=NOW() RETURNING id`,
      [sourceId,file,uri,'T41 figura '+asset.figure,
       'Recorte literal sin rotulos CEIS pag. '+asset.printed_page,
       'CEIS Guadalajara, Parte 6, pag. '+asset.printed_page]);
      imgMap.set(file,{id:Number(q.rows[0].id),uri,sourceId});
    }
    let imported=0;
    for(const row of data.questions){
      const img=imgMap.get(row.graphic_file);
      if(!img||row.image_sha256!==data.images.find(i=>i.file===row.graphic_file)?.sha256||
         !/^T41-GRAF-\d{4}$/.test(row.external_key)||
         !Array.isArray(row.options)||row.options.length!==4||
         new Set(row.options).size!==4||
         !Number.isInteger(row.correct_index)||row.correct_index<0||row.correct_index>3||
         row.question_family!=='GRAFICA'||row.difficulty!=='muy alta'||
         !row.stem||!row.source_evidence)
        throw Error('T41: pregunta no valida '+row.external_key);
      const key=row.external_key+' · '+row.coverage_concept;
      const c=await client.query(`INSERT INTO coverage_items(topic_id,section,concept,
        item_type,evaluation_type,source_page,manual_page,source_evidence,exam_relevant)
        VALUES($1,$2,$3,'grafica_t41_original','interpretacion_visual',$4,$5,$6,TRUE)
        ON CONFLICT(topic_id,concept,item_type,evaluation_type) DO UPDATE SET
        section=EXCLUDED.section,source_page=EXCLUDED.source_page,
        manual_page=EXCLUDED.manual_page,source_evidence=EXCLUDED.source_evidence,
        exam_relevant=TRUE RETURNING id`,
      [t.id,row.coverage_section,key,row.source_pdf_page,row.manual_page,row.source_evidence]);
      const coverageId=Number(c.rows[0].id);
      const graphic={...row.graphic,assetId:img.id,publicUrl:img.uri,
        sourceId:img.sourceId,assetType:'individual',
        crop:{x:0,y:0,width:1,height:1},maskRegions:[]};
      const previous=await client.query(`SELECT id,stem,options,correct_index FROM question_bank
        WHERE coverage_item_id=$1 AND question_family='GRAFICA' ORDER BY id DESC
        LIMIT 1 FOR UPDATE`,[coverageId]);
      if(previous.rows.length){
        const old=previous.rows[0];
        if(old.stem!==row.stem||JSON.stringify(old.options)!==JSON.stringify(row.options)||
          Number(old.correct_index)!==Number(row.correct_index))
          throw Error('T41: pregunta distinta ya existente: '+row.external_key);
        await client.query(`UPDATE question_bank SET active=TRUE,graphic=$2::jsonb,
          updated_at=NOW() WHERE id=$1`,[old.id,JSON.stringify(graphic)]);
      }else await client.query(`INSERT INTO question_bank(coverage_item_id,stem,options,
        correct_index,explanation,source_evidence,source_page,manual_page,
        question_family,difficulty,graphic,validation_version,active)
        VALUES($1,$2,$3::jsonb,$4,$5,$6,$7,$8,'GRAFICA','muy alta',$9::jsonb,6,TRUE)`,
        [coverageId,row.stem,JSON.stringify(row.options),row.correct_index,
        row.explanation,row.source_evidence,row.source_pdf_page,row.manual_page,
        JSON.stringify(graphic)]);
      imported++;
    }
    if(imported!==50)throw Error('T41: numero de preguntas importadas incompleto');
    // Corrección ACOTADA y documentada T41/CEIS p244: cuatro respuestas
    // de umbral eran simultáneamente verdaderas para la pregunta 1468.
    // Se conserva su id y estadísticas (SRS), se corrige SOLO stem/opciones.
    const t41q=await client.query(`SELECT id,stem,options,correct_index,manual_page
      FROM question_bank WHERE id=$1 AND coverage_item_id=$2 FOR UPDATE`,
      [1468,24661]);
    if(t41q.rows.length){
      const old=t41q.rows[0];
      const oldOpts=['Superó las 12.000 ha','Superó las 18.000 ha',
        'Superó las 25.000 ha','Superó las 15.000 ha'];
      const newOpts=[
        'El manual fija exactamente en 18.000 ha la superficie afectada en 2013.',
        'El manual afirma que se superaron las 18.000 ha, sin indicar una cifra exacta.',
        'El manual señala que la superficie de 2013 fue inferior a 18.000 ha.',
        'El manual no aporta ningún umbral de superficie para el año 2013.'
      ];
      const newStem='Según el CEIS Guadalajara, página 244, ¿qué información recoge literalmente sobre la superficie afectada por incendios forestales en España en 2013?';
      const prev=JSON.stringify(old.options);
      if(String(old.manual_page)!=='244'||Number(old.correct_index)!==1)
        throw Error('T41-186: pregunta 1468 no corresponde a la ficha auditada');
      if(prev===JSON.stringify(oldOpts)){
        await client.query(`UPDATE question_bank SET stem=$2,options=$3::jsonb,
          correct_index=1,explanation=$4,updated_at=NOW()
          WHERE id=$1 AND coverage_item_id=24661`,[1468,newStem,
          JSON.stringify(newOpts),
          'La página 244 del CEIS solo afirma que en 2013 se superaron las 18.000 ha; no proporciona un total exacto.']);
      }else if(prev!==JSON.stringify(newOpts)||old.stem!==newStem){
        throw Error('T41-186: pregunta 1468 modificada externamente; no se sobrescribe');
      }
    }
    await client.query(`UPDATE graphic_assets SET is_usable=FALSE,updated_at=NOW()
      WHERE topic_folder='incendios-vegetacion' AND source_file LIKE 'Screenshot_%'
      AND is_usable=TRUE`);
    await client.query(`UPDATE topics SET
      name='TEMA 41. INCENDIOS DE VEGETACIÓN E INTERFAZ URBANO-FORESTAL',
      total_items=(SELECT COUNT(*) FROM coverage_items
        WHERE topic_id=$1 AND exam_relevant=TRUE) WHERE id=$1`,[t.id]);
    await client.query('COMMIT');
    console.log('T41_GRAFICOS_CARGADOS',JSON.stringify({topicId:t.id,
      images:11,questions:50,documentaryAdditions:data.coverage_additions.length,
      pdfSha256:fileHash}));
    return {ok:true,topicId:t.id,images:11,questions:50,
      documentaryAdditions:data.coverage_additions.length};
  }catch(e){await client.query('ROLLBACK');throw e;}
  finally{client.release();}
}
async function t41GraphicBankPairs(topicId,freshOnly,difficulty){
  if(difficulty!=='muy alta')return [];
  const rows=await db.query(`SELECT qb.id AS question_id,qb.stem,qb.options,
      qb.correct_index,qb.explanation,qb.source_evidence,qb.source_page,
      qb.manual_page,qb.question_family,qb.difficulty,qb.graphic,qb.validation_version,
      ci.id AS coverage_id,ci.topic_id,ci.section,ci.concept,ci.item_type,
      ci.evaluation_type,ci.source_evidence AS ci_evidence,ci.source_page AS ci_page,
      ci.manual_page AS ci_manual,t.name AS topic_name,t.block AS topic_block
    FROM question_bank qb JOIN coverage_items ci ON ci.id=qb.coverage_item_id
    JOIN topics t ON t.id=ci.topic_id
    LEFT JOIN coverage_review_state crs ON crs.coverage_item_id=ci.id
    WHERE ci.topic_id=$1 AND ci.item_type='grafica_t41_original'
      AND ci.exam_relevant=TRUE AND qb.active=TRUE
      AND qb.question_family='GRAFICA' AND qb.difficulty='muy alta'
      AND qb.validation_version>=6 AND ${SRS96_ELIGIBLE_SQL}
      AND ($2::boolean=FALSE OR (${FRESH111_SQL}))
    ORDER BY ci.times_asked ASC,qb.times_shown ASC,qb.id ASC LIMIT 120`,
    [topicId,Boolean(freshOnly)]);
  return rows.rows;
}


/* TEMA 42: SOLO importación documental/gráfica idempotente. Sin tocar otros temas. */
let t42PreparedData=null;
function t42Topic(topic){
  const name=String(topic?.name||topic?.topic_name||'').normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'').replace(/[_-]+/g,' ');
  return /^\s*tema\s*42\b/i.test(name) &&
    /incendios?\s+en\s+tuneles/i.test(name) &&
    String(topic?.block||topic?.topic_block||'').toLowerCase()==='especifico';
}
function t42LoadData(){
  if(t42PreparedData)return t42PreparedData;
  const file=path.join(process.cwd(),'t42_graphics_data.js');
  if(!fs.existsSync(file))return null;
  const content=fs.readFileSync(file,'utf8');
  const marker='module.exports = ';
  const start=content.indexOf(marker);
  if(start<0)throw Error('T42: cabecera de paquete grafico invalida');
  const data=JSON.parse(content.slice(start+marker.length).trim().replace(/;\s*$/,''));
  if(data?.schema!==1||data.topic_number!==42||data.pdf_page_count!==22||
     !Array.isArray(data.images)||data.images.length!==15||
     !Array.isArray(data.questions)||data.questions.length!==90||
     new Set(data.images.map(x=>x.file)).size!==15||
     new Set(data.questions.map(x=>x.external_key)).size!==90||
     !Array.isArray(data.coverage_additions)||
     data.coverage_additions.length!==179||
     data.questions.some(q=>/runehamar|ensayos?|pruebas\s+realizadas/i.test(String(q.stem||''))))
    throw Error('T42: recortes, datos o preguntas incompletos o excluidos');
  if(data.coverage_additions.some(item=>/^\s*Tabla\s*[678]\s*[.:]/i.test(String(item.section||''))))
    throw Error('T42: el paquete contiene tablas experimentales 6, 7 u 8 excluidas');
  t42PreparedData=data;return data;
}
function t42WriteImages(){
  const data=t42LoadData();if(!data)return {skipped:true};
  const dir=path.join(process.cwd(),'public','graphics','incendios-tuneles');
  fs.mkdirSync(dir,{recursive:true});let written=0;
  for(const asset of data.images){
    if(!/^T42_FIG_\d{2}_P\d{3}\.png$/.test(asset.file))
      throw Error('T42: nombre de imagen inesperado');
    const buf=Buffer.from(asset.base64,'base64');
    const sha=createHash('sha256').update(buf).digest('hex');
    if(sha!==asset.sha256||!buf.subarray(0,8)
      .equals(Buffer.from([137,80,78,71,13,10,26,10])))
      throw Error('T42: checksum/png invalido '+asset.file);
    const dest=path.join(dir,asset.file);
    if(fs.existsSync(dest)){
      if(createHash('sha256').update(fs.readFileSync(dest)).digest('hex')!==sha)
        throw Error('T42: fichero de imagen existente distinto '+asset.file);
    }else{fs.writeFileSync(dest,buf);written++;}
  }
  return {images:15,written};
}
// T42-186: verified DOCUMENT-only repair. No changes outside Tema 42.
// These specific records describe laboratory exercises, not generic knowledge;
 // the user excluded studies in p.185 and the three experimental tables p.186-187.
const T42_186_RETIRED_BY_PAGE=Object.freeze({
  185:[25596,25597,25598,25599,25600,25601,25602,25603],
  186:[25608,25609,25610,25611,25612,25615,25618,25619,25620],
  187:[25621,25623,25624],
  191:[25649] // editorial contradiction in monobottle usage (15-20 vs >20-30 min).
});
async function t42RepairCoverage186(client,topicId){
  const expected=new Map(Object.entries(T42_186_RETIRED_BY_PAGE)
    .flatMap(([page,ids])=>ids.map(id=>[id,String(page)])));
  const ids=[...expected.keys()];
  const result=await client.query(`SELECT id,manual_page,exam_relevant
    FROM coverage_items WHERE topic_id=$1 AND id=ANY($2::int[]) FOR UPDATE`,
    [topicId,ids]);
  for(const row of result.rows){
    if(String(row.manual_page)!==expected.get(Number(row.id)))
      throw Error('T42-186: record page mismatch: '+row.id);
  }
  const present=result.rows.map(row=>Number(row.id));
  const retired=await client.query(`UPDATE coverage_items
    SET exam_relevant=FALSE
    WHERE topic_id=$1 AND id=ANY($2::int[]) AND exam_relevant=TRUE
    RETURNING id`,[topicId,present]);
  if(present.length){
    await client.query(`UPDATE question_bank SET active=FALSE,updated_at=NOW()
      WHERE coverage_item_id=ANY($1::int[]) AND active=TRUE`,[present]);
  }
  // The printed formula has a factor 1/3 before Q/(4*pi*R^2).
  // The extracted record had omitted that factor. Preserve source PDF unchanged.
  const oldFormula=await client.query(`SELECT id,concept,source_evidence,manual_page
    FROM coverage_items WHERE topic_id=$1 AND id=25616 FOR UPDATE`,[topicId]);
  let formulaFixed=false;
  if(oldFormula.rows.length){
    const row=oldFormula.rows[0];
    if(String(row.manual_page)!=='186')
      throw Error('T42-186: formula page mismatch');
    if(!String(row.concept||'').includes('(1/3)')){
      if(!String(row.concept||'').includes('qs = Q / (4 * pi * R^2)'))
        throw Error('T42-186: formula does not match audited record');
      await client.query(`UPDATE coverage_items SET concept=$2,source_evidence=$3
        WHERE topic_id=$1 AND id=25616`,[topicId,
        "Ecuación de radiación CEIS p. 186: q_s'' = (1/3) × Q / (4πR²)",
        "Ecuación reproducida visualmente de CEIS p.186: q_s'' = (1/3) × Q / (4πR²); q_s'' es radiación, Q tasa total de emisión de calor y R distancia desde la fuente puntual efectiva."]);
      await client.query(`UPDATE question_bank SET active=FALSE,updated_at=NOW()
        WHERE coverage_item_id=25616 AND active=TRUE`);
      formulaFixed=true;
    }
  }
  return {retiredNow:retired.rows.length,presentKnownRecords:present.length,
    formulaFixed,retirementExpected:ids.length};
}
async function t42ImportOnce(topic,uploadedPdfPath=null){
  if(!t42Topic(topic))return {skipped:true};
  const data=t42LoadData();if(!data)return {skipped:true,missing:true};
  t42WriteImages();
  const client=await db.connect();
  try{
    await client.query('BEGIN');
    const topics=await client.query('SELECT * FROM topics WHERE id=$1 FOR UPDATE',[topic.id]);
    const t=topics.rows[0];
    // Importación solo cuando la fuente de la indexación coincide.
    // Si se llama desde el formulario, verificar el SHA del PDF subido.
    // Al reintentar en el arranque, exigir el nombre del PDF oficial suministrado.
    if(uploadedPdfPath){
      const uploaded=fs.readFileSync(uploadedPdfPath);
      if(createHash('sha256').update(uploaded).digest('hex')!==data.pdf_sha256)
        throw Error('T42: SHA del PDF realmente indexado distinto del paquete');
    }else if(String(t.source_file||'')!==String(data.pdf_filename)){
      throw Error('T42: fuente del tema no coincide con el PDF preparado');
    }
    // T42-179: conservar la indexación File Search existente. Su PDF no se
    // guardaba localmente, pero el banco fijo de imágenes exigía ese registro.
    // El PDF exacto se incorpora en el paquete con SHA verificado.
    if(!t42Topic(t)||Number(t.total_items)<1||!t.file_search_indexed)
      throw Error('T42: tema no indexado; no se altera ninguna cobertura');
    const remote=await client.query(`SELECT document_name
      FROM topic_source_documents WHERE topic_id=$1`,[t.id]);
    if(!remote.rows[0]?.document_name)
      throw Error('T42: no hay fuente File Search vinculada; no se suplanta');
    if(!data.pdf_base64||!Array.isArray(data.coverage_additions))
      throw Error('T42: falta el PDF original y el inventario de ampliaciones');
    const pdfBytes=Buffer.from(data.pdf_base64,'base64');
    const fileHash=createHash('sha256').update(pdfBytes).digest('hex');
    if(fileHash!==data.pdf_sha256||pdfBytes.length<1000||
       pdfBytes.length>20*1024*1024||
       pdfBytes.subarray(0,5).toString('latin1')!=='%PDF-')
      throw Error('T42: PDF local distinto del original indexado');
    const source=await PDFDocument.load(pdfBytes,{updateMetadata:false});
    if(source.getPageCount()!==22)throw Error('T42: el PDF no tiene 22 páginas');
    await client.query(`INSERT INTO topic_local_pdfs
      (topic_id,pdf_sha256,page_count,size_bytes,pdf_bytes)
      VALUES($1,$2,22,$3,$4) ON CONFLICT(topic_id) DO NOTHING`,
      [t.id,fileHash,pdfBytes.length,pdfBytes]);
    const stored=await client.query(`SELECT TRIM(pdf_sha256) AS sha,
      page_count,size_bytes,OCTET_LENGTH(pdf_bytes) AS stored_size,
      encode(sha256(pdf_bytes),'hex') AS stored_sha
      FROM topic_local_pdfs WHERE topic_id=$1`,[t.id]);
    const check=stored.rows[0];
    if(!check||check.sha!==fileHash||check.stored_sha!==fileHash||
       Number(check.page_count)!==22||
       Number(check.size_bytes)!==pdfBytes.length||
       Number(check.stored_size)!==pdfBytes.length)
      throw Error('T42: copia PDF local incompatible; no se sobrescribe');
    // Retirar solamente conocimientos experimentales no examinables y corregir
    // la fórmula que se transcribió sin el factor 1/3.
    const t42Repair=t42RepairCoverage186(client,t.id);
    // La reparación se realiza en la MISMA transacción que la importación.
    const repair186=await t42Repair;
    // Completar únicamente lagunas verificadas contra páginas físicas.
    // DO NOTHING preserva historial y SRS si ya se instaló antes.
    for(const item of data.coverage_additions){
      const tab=/^T42-TAB-\d{4}$/.test(item.external_key);
      const text=/^T42-TXT-\d{4}$/.test(item.external_key);
      if((!tab&&!text)||
         !Number.isInteger(item.source_page)||item.source_page<1||item.source_page>22||
         String(item.manual_page)!==String(item.source_page+174)||
         !item.concept||!item.source_evidence)
        throw Error('T42: ampliación documental no válida');
      await client.query(`INSERT INTO coverage_items(topic_id,section,concept,
        item_type,evaluation_type,source_page,manual_page,source_evidence,exam_relevant)
        VALUES($1,$2,$3,$4,'literal_documental',$5,$6,$7,TRUE)
        ON CONFLICT(topic_id,concept,item_type,evaluation_type) DO NOTHING`,
        [t.id,item.section,item.external_key+' · '+item.concept,
         tab?'tabla_t42':'concepto_t42_revisado',
         item.source_page,item.manual_page,item.source_evidence]);
    }
    const imgMap=new Map();
    for(const asset of data.images){
      const file=asset.file,uri='/graphics/incendios-tuneles/'+file;
      const sourceId='incendios-tuneles/'+file;
      const q=await client.query(`INSERT INTO graphic_assets(
        source_id,topic_folder,source_file,public_url,asset_index,asset_type,
        concept,description,source_evidence,crop_x,crop_y,crop_width,crop_height,
        mask_regions,is_official_reference,is_usable,analysis_status,sanitization_version)
        VALUES($1,'incendios-tuneles',$2,$3,0,'individual',$4,$5,$6,
        0,0,1,1,'[]'::jsonb,FALSE,TRUE,'analyzed',2)
        ON CONFLICT(source_id,asset_index) DO UPDATE SET
        concept=EXCLUDED.concept,description=EXCLUDED.description,
        source_evidence=EXCLUDED.source_evidence,public_url=EXCLUDED.public_url,
        crop_x=0,crop_y=0,crop_width=1,crop_height=1,
        mask_regions='[]'::jsonb,is_usable=TRUE,analysis_status='analyzed',
        sanitization_version=2,updated_at=NOW() RETURNING id`,
      [sourceId,file,uri,'T42 figura '+asset.figure,
       'Recorte literal sin rotulos CEIS pag. '+asset.printed_page,
       'CEIS Guadalajara, Parte 4, pag. '+asset.printed_page]);
      imgMap.set(file,{id:Number(q.rows[0].id),uri,sourceId});
    }
    let imported=0;
    for(const row of data.questions){
      const img=imgMap.get(row.graphic_file);
      if(!img||row.image_sha256!==data.images.find(i=>i.file===row.graphic_file)?.sha256||
         !/^T42-GRAF-\d{4}$/.test(row.external_key)||
         !Array.isArray(row.options)||row.options.length!==4||
         new Set(row.options).size!==4||
         !Number.isInteger(row.correct_index)||row.correct_index<0||row.correct_index>3||
         row.question_family!=='GRAFICA'||row.difficulty!=='muy alta'||
         !row.stem||!row.source_evidence)
        throw Error('T42: pregunta no valida '+row.external_key);
      const key=row.external_key+' · '+row.coverage_concept;
      const c=await client.query(`INSERT INTO coverage_items(topic_id,section,concept,
        item_type,evaluation_type,source_page,manual_page,source_evidence,exam_relevant)
        VALUES($1,$2,$3,'grafica_t42_original','interpretacion_visual',$4,$5,$6,TRUE)
        ON CONFLICT(topic_id,concept,item_type,evaluation_type) DO UPDATE SET
        section=EXCLUDED.section,source_page=EXCLUDED.source_page,
        manual_page=EXCLUDED.manual_page,source_evidence=EXCLUDED.source_evidence,
        exam_relevant=TRUE RETURNING id`,
      [t.id,row.coverage_section,key,row.source_pdf_page,row.manual_page,row.source_evidence]);
      const coverageId=Number(c.rows[0].id);
      const graphic={...row.graphic,assetId:img.id,publicUrl:img.uri,
        sourceId:img.sourceId,assetType:'individual',
        crop:{x:0,y:0,width:1,height:1},maskRegions:[]};
      const previous=await client.query(`SELECT id,stem,options,correct_index FROM question_bank
        WHERE coverage_item_id=$1 AND question_family='GRAFICA' ORDER BY id DESC
        LIMIT 1 FOR UPDATE`,[coverageId]);
      if(previous.rows.length){
        const old=previous.rows[0];
        if(old.stem!==row.stem||JSON.stringify(old.options)!==JSON.stringify(row.options)||
          Number(old.correct_index)!==Number(row.correct_index))
          throw Error('T42: pregunta distinta ya existente: '+row.external_key);
        await client.query(`UPDATE question_bank SET active=TRUE,graphic=$2::jsonb,
          updated_at=NOW() WHERE id=$1`,[old.id,JSON.stringify(graphic)]);
      }else await client.query(`INSERT INTO question_bank(coverage_item_id,stem,options,
        correct_index,explanation,source_evidence,source_page,manual_page,
        question_family,difficulty,graphic,validation_version,active)
        VALUES($1,$2,$3::jsonb,$4,$5,$6,$7,$8,'GRAFICA','muy alta',$9::jsonb,6,TRUE)`,
        [coverageId,row.stem,JSON.stringify(row.options),row.correct_index,
        row.explanation,row.source_evidence,row.source_pdf_page,row.manual_page,
        JSON.stringify(graphic)]);
      imported++;
    }
    if(imported!==90)throw Error('T42: numero de preguntas importadas incompleto');
    await client.query(`UPDATE graphic_assets SET is_usable=FALSE,updated_at=NOW()
      WHERE topic_folder='incendios-tuneles' AND source_file LIKE 'Screenshot_%'
      AND is_usable=TRUE`);
    await client.query(`UPDATE topics SET
      name='TEMA 42. INCENDIOS EN TÚNELES',
      total_items=(SELECT COUNT(*) FROM coverage_items
        WHERE topic_id=$1 AND exam_relevant=TRUE) WHERE id=$1`,[t.id]);
    await client.query('COMMIT');
    console.log('T42_GRAFICOS_CARGADOS',JSON.stringify({topicId:t.id,
      images:15,questions:90,documentaryAdditions:data.coverage_additions.length,
      repair186,pdfSha256:fileHash}));
    return {ok:true,topicId:t.id,images:15,questions:90,
      repair186,documentaryAdditions:data.coverage_additions.length};
  }catch(e){await client.query('ROLLBACK');throw e;}
  finally{client.release();}
}
async function t42GraphicBankPairs(topicId,freshOnly,difficulty){
  if(difficulty!=='muy alta')return [];
  const rows=await db.query(`SELECT qb.id AS question_id,qb.stem,qb.options,
      qb.correct_index,qb.explanation,qb.source_evidence,qb.source_page,
      qb.manual_page,qb.question_family,qb.difficulty,qb.graphic,qb.validation_version,
      ci.id AS coverage_id,ci.topic_id,ci.section,ci.concept,ci.item_type,
      ci.evaluation_type,ci.source_evidence AS ci_evidence,ci.source_page AS ci_page,
      ci.manual_page AS ci_manual,t.name AS topic_name,t.block AS topic_block
    FROM question_bank qb JOIN coverage_items ci ON ci.id=qb.coverage_item_id
    JOIN topics t ON t.id=ci.topic_id
    LEFT JOIN coverage_review_state crs ON crs.coverage_item_id=ci.id
    WHERE ci.topic_id=$1 AND ci.item_type='grafica_t42_original'
      AND ci.exam_relevant=TRUE AND qb.active=TRUE
      AND qb.question_family='GRAFICA' AND qb.difficulty='muy alta'
      AND qb.validation_version>=6 AND ${SRS96_ELIGIBLE_SQL}
      AND ($2::boolean=FALSE OR (${FRESH111_SQL}))
    ORDER BY ci.times_asked ASC,qb.times_shown ASC,qb.id ASC LIMIT 120`,
    [topicId,Boolean(freshOnly)]);
  return rows.rows;
}




/* T43: módulo documental/gráfico aislado, sin modificación de otros temas. */
/* TEMA 43: SOLO importación documental/gráfica idempotente. Sin tocar otros temas. */
let t43PreparedData=null;
function t43Topic(topic){
  const name=String(topic?.name||topic?.topic_name||'').normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'').replace(/[_-]+/g,' ');
  return /^\s*tema\s*43\b/i.test(name) &&
    /rescate\s+en\s+accidentes?\s+ferroviarios/i.test(name) &&
    String(topic?.block||topic?.topic_block||'').toLowerCase()==='especifico';
}
function t43LoadData(){
  if(t43PreparedData)return t43PreparedData;
  const file=path.join(process.cwd(),'t43_graphics_data.js');
  if(!fs.existsSync(file))return null;
  const content=fs.readFileSync(file,'utf8');
  const marker='module.exports = ';
  const start=content.indexOf(marker);
  if(start<0)throw Error('T43: cabecera de paquete grafico invalida');
  const data=JSON.parse(content.slice(start+marker.length).trim().replace(/;\s*$/,''));
  if(data?.schema!==1||data.topic_number!==43||data.pdf_page_count!==24||
     !Array.isArray(data.images)||data.images.length!==11||
     !Array.isArray(data.questions)||data.questions.length!==86||
     new Set(data.images.map(x=>x.file)).size!==11||
     new Set(data.questions.map(x=>x.external_key)).size!==86)
    throw Error('T43: recortes o preguntas incompletos o repetidos');
  t43PreparedData=data;return data;
}
function t43WriteImages(){
  const data=t43LoadData();if(!data)return {skipped:true};
  const dir=path.join(process.cwd(),'public','graphics','ferroviarios');
  fs.mkdirSync(dir,{recursive:true});let written=0;
  for(const asset of data.images){
    if(!/^T43_FIG_\d{2}_P\d{3}\.png$/.test(asset.file))
      throw Error('T43: nombre de imagen inesperado');
    const buf=Buffer.from(asset.base64,'base64');
    const sha=createHash('sha256').update(buf).digest('hex');
    if(sha!==asset.sha256||!buf.subarray(0,8)
      .equals(Buffer.from([137,80,78,71,13,10,26,10])))
      throw Error('T43: checksum/png invalido '+asset.file);
    const dest=path.join(dir,asset.file);
    if(fs.existsSync(dest)){
      if(createHash('sha256').update(fs.readFileSync(dest)).digest('hex')!==sha)
        throw Error('T43: fichero de imagen existente distinto '+asset.file);
    }else{fs.writeFileSync(dest,buf);written++;}
  }
  return {images:11,written};
}
async function t43ImportOnce(topic,uploadedPdfPath=null){
  if(!t43Topic(topic))return {skipped:true};
  const data=t43LoadData();if(!data)return {skipped:true,missing:true};
  t43WriteImages();
  const client=await db.connect();
  try{
    await client.query('BEGIN');
    const topics=await client.query('SELECT * FROM topics WHERE id=$1 FOR UPDATE',[topic.id]);
    const t=topics.rows[0];
    // Importación solo cuando la fuente de la indexación coincide.
    // Si se llama desde el formulario, verificar el SHA del PDF subido.
    // Al reintentar en el arranque, exigir el nombre del PDF oficial suministrado.
    if(uploadedPdfPath){
      const uploaded=fs.readFileSync(uploadedPdfPath);
      if(createHash('sha256').update(uploaded).digest('hex')!==data.pdf_sha256)
        throw Error('T43: SHA del PDF realmente indexado distinto del paquete');
    }else if(String(t.source_file||'')!==String(data.pdf_filename)){
      // Un PDF verificado puede haberse subido con otro nombre. No confiar
      // en el nombre: aceptar SOLO si ya existe su copia local íntegra,
      // enlazada a este tema y con el SHA exacto del CEIS.
      const linked=await client.query(`SELECT trim(pdf_sha256) AS sha,
        encode(sha256(pdf_bytes),'hex') AS actual_sha, page_count
        FROM topic_local_pdfs WHERE topic_id=$1`,[t.id]);
      const fp=linked.rows[0];
      if(!fp||fp.sha!==data.pdf_sha256||fp.actual_sha!==data.pdf_sha256||
         Number(fp.page_count)!==24)
        throw Error('T43: fuente PDF distinta y sin copia local validada');
    }
    // T43-179: conservar la indexación File Search existente. Su PDF no se
    // guardaba localmente, pero el banco fijo de imágenes exigía ese registro.
    // El PDF exacto se incorpora en el paquete con SHA verificado.
    if(!t43Topic(t)||Number(t.total_items)<1||!t.file_search_indexed)
      throw Error('T43: tema no indexado; no se altera ninguna cobertura');
    const remote=await client.query(`SELECT document_name
      FROM topic_source_documents WHERE topic_id=$1`,[t.id]);
    if(!remote.rows[0]?.document_name)
      throw Error('T43: no hay fuente File Search vinculada; no se suplanta');
    if(!data.pdf_base64||!Array.isArray(data.coverage_additions))
      throw Error('T43: falta el PDF original y el inventario de ampliaciones');
    const pdfBytes=Buffer.from(data.pdf_base64,'base64');
    const fileHash=createHash('sha256').update(pdfBytes).digest('hex');
    if(fileHash!==data.pdf_sha256||pdfBytes.length<1000||
       pdfBytes.length>20*1024*1024||
       pdfBytes.subarray(0,5).toString('latin1')!=='%PDF-')
      throw Error('T43: PDF local distinto del original indexado');
    const source=await PDFDocument.load(pdfBytes,{updateMetadata:false});
    if(source.getPageCount()!==24)throw Error('T43: el PDF no tiene 24 páginas');
    await client.query(`INSERT INTO topic_local_pdfs
      (topic_id,pdf_sha256,page_count,size_bytes,pdf_bytes)
      VALUES($1,$2,24,$3,$4) ON CONFLICT(topic_id) DO NOTHING`,
      [t.id,fileHash,pdfBytes.length,pdfBytes]);
    const stored=await client.query(`SELECT TRIM(pdf_sha256) AS sha,
      page_count,size_bytes,OCTET_LENGTH(pdf_bytes) AS stored_size,
      encode(sha256(pdf_bytes),'hex') AS stored_sha
      FROM topic_local_pdfs WHERE topic_id=$1`,[t.id]);
    const check=stored.rows[0];
    if(!check||check.sha!==fileHash||check.stored_sha!==fileHash||
       Number(check.page_count)!==24||
       Number(check.size_bytes)!==pdfBytes.length||
       Number(check.stored_size)!==pdfBytes.length)
      throw Error('T43: copia PDF local incompatible; no se sobrescribe');
    // Completar únicamente lagunas verificadas contra páginas físicas.
    // DO NOTHING preserva historial y SRS si ya se instaló antes.
    for(const item of data.coverage_additions){
      if(!/^T43-(?:TAB|NUM)-\d{4}$/.test(item.external_key)||
         !Number.isInteger(item.source_page)||item.source_page<1||item.source_page>22||
         !item.concept||!item.source_evidence)
        throw Error('T43: ampliación documental no válida');
      await client.query(`INSERT INTO coverage_items(topic_id,section,concept,
        item_type,evaluation_type,source_page,manual_page,source_evidence,exam_relevant)
        VALUES($1,$2,$3,'dato_t43_preparado','literal_documental',$4,$5,$6,TRUE)
        ON CONFLICT(topic_id,concept,item_type,evaluation_type) DO NOTHING`,
        [t.id,item.section,item.external_key+' · '+item.concept,
         item.source_page,item.manual_page,item.source_evidence]);
    }
    const imgMap=new Map();
    for(const asset of data.images){
      const file=asset.file,uri='/graphics/ferroviarios/'+file;
      const sourceId='ferroviarios/'+file;
      const q=await client.query(`INSERT INTO graphic_assets(
        source_id,topic_folder,source_file,public_url,asset_index,asset_type,
        concept,description,source_evidence,crop_x,crop_y,crop_width,crop_height,
        mask_regions,is_official_reference,is_usable,analysis_status,sanitization_version)
        VALUES($1,'ferroviarios',$2,$3,0,'individual',$4,$5,$6,
        0,0,1,1,'[]'::jsonb,FALSE,TRUE,'analyzed',2)
        ON CONFLICT(source_id,asset_index) DO UPDATE SET
        concept=EXCLUDED.concept,description=EXCLUDED.description,
        source_evidence=EXCLUDED.source_evidence,public_url=EXCLUDED.public_url,
        crop_x=0,crop_y=0,crop_width=1,crop_height=1,
        mask_regions='[]'::jsonb,is_usable=TRUE,analysis_status='analyzed',
        sanitization_version=2,updated_at=NOW() RETURNING id`,
      [sourceId,file,uri,'T43 figura '+asset.figure,
       'Recorte original delimitado al contenido gráfico CEIS pag. '+asset.printed_page,
       'CEIS Guadalajara, Parte 6, pag. '+asset.printed_page]);
      imgMap.set(file,{id:Number(q.rows[0].id),uri,sourceId});
    }
    let imported=0;
    for(const row of data.questions){
      const img=imgMap.get(row.graphic_file);
      if(!img||row.image_sha256!==data.images.find(i=>i.file===row.graphic_file)?.sha256||
         !/^T43-GRAF-\d{4}$/.test(row.external_key)||
         !Array.isArray(row.options)||row.options.length!==4||
         new Set(row.options).size!==4||
         !Number.isInteger(row.correct_index)||row.correct_index<0||row.correct_index>3||
         row.question_family!=='GRAFICA'||row.difficulty!=='muy alta'||
         !row.stem||!row.source_evidence)
        throw Error('T43: pregunta no valida '+row.external_key);
      const key=row.external_key+' · '+row.coverage_concept;
      const c=await client.query(`INSERT INTO coverage_items(topic_id,section,concept,
        item_type,evaluation_type,source_page,manual_page,source_evidence,exam_relevant)
        VALUES($1,$2,$3,'grafica_t43_original','interpretacion_visual',$4,$5,$6,TRUE)
        ON CONFLICT(topic_id,concept,item_type,evaluation_type) DO UPDATE SET
        section=EXCLUDED.section,source_page=EXCLUDED.source_page,
        manual_page=EXCLUDED.manual_page,source_evidence=EXCLUDED.source_evidence,
        exam_relevant=TRUE RETURNING id`,
      [t.id,row.coverage_section,key,row.source_pdf_page,row.manual_page,row.source_evidence]);
      const coverageId=Number(c.rows[0].id);
      const graphic={...row.graphic,assetId:img.id,publicUrl:img.uri,
        sourceId:img.sourceId,assetType:'individual',
        crop:{x:0,y:0,width:1,height:1},maskRegions:[]};
      const previous=await client.query(`SELECT id,stem,options,correct_index FROM question_bank
        WHERE coverage_item_id=$1 AND question_family='GRAFICA' ORDER BY id DESC
        LIMIT 1 FOR UPDATE`,[coverageId]);
      if(previous.rows.length){
        const old=previous.rows[0];
        if(old.stem!==row.stem||JSON.stringify(old.options)!==JSON.stringify(row.options)||
          Number(old.correct_index)!==Number(row.correct_index))
          throw Error('T43: pregunta distinta ya existente: '+row.external_key);
        await client.query(`UPDATE question_bank SET active=TRUE,graphic=$2::jsonb,
          updated_at=NOW() WHERE id=$1`,[old.id,JSON.stringify(graphic)]);
      }else await client.query(`INSERT INTO question_bank(coverage_item_id,stem,options,
        correct_index,explanation,source_evidence,source_page,manual_page,
        question_family,difficulty,graphic,validation_version,active)
        VALUES($1,$2,$3::jsonb,$4,$5,$6,$7,$8,'GRAFICA','muy alta',$9::jsonb,6,TRUE)`,
        [coverageId,row.stem,JSON.stringify(row.options),row.correct_index,
        row.explanation,row.source_evidence,row.source_pdf_page,row.manual_page,
        JSON.stringify(graphic)]);
      imported++;
    }
    if(imported!==86)throw Error('T43: numero de preguntas importadas incompleto');
    await client.query(`UPDATE graphic_assets SET is_usable=FALSE,updated_at=NOW()
      WHERE topic_folder='ferroviarios' AND source_file LIKE 'Screenshot_%'
      AND is_usable=TRUE`);
    await client.query(`UPDATE topics SET
      name='TEMA 43. RESCATE EN ACCIDENTES FERROVIARIOS',
      total_items=(SELECT COUNT(*) FROM coverage_items
        WHERE topic_id=$1 AND exam_relevant=TRUE) WHERE id=$1`,[t.id]);
    await client.query('COMMIT');
    console.log('T43_GRAFICOS_CARGADOS',JSON.stringify({topicId:t.id,
      images:11,questions:86,documentaryAdditions:data.coverage_additions.length,
      pdfSha256:fileHash}));
    return {ok:true,topicId:t.id,images:11,questions:86,
      documentaryAdditions:data.coverage_additions.length};
  }catch(e){await client.query('ROLLBACK');throw e;}
  finally{client.release();}
}
async function t43GraphicBankPairs(topicId,freshOnly,difficulty){
  if(difficulty!=='muy alta')return [];
  const rows=await db.query(`SELECT qb.id AS question_id,qb.stem,qb.options,
      qb.correct_index,qb.explanation,qb.source_evidence,qb.source_page,
      qb.manual_page,qb.question_family,qb.difficulty,qb.graphic,qb.validation_version,
      ci.id AS coverage_id,ci.topic_id,ci.section,ci.concept,ci.item_type,
      ci.evaluation_type,ci.source_evidence AS ci_evidence,ci.source_page AS ci_page,
      ci.manual_page AS ci_manual,t.name AS topic_name,t.block AS topic_block
    FROM question_bank qb JOIN coverage_items ci ON ci.id=qb.coverage_item_id
    JOIN topics t ON t.id=ci.topic_id
    LEFT JOIN coverage_review_state crs ON crs.coverage_item_id=ci.id
    WHERE ci.topic_id=$1 AND ci.item_type='grafica_t43_original'
      AND ci.exam_relevant=TRUE AND qb.active=TRUE
      AND qb.question_family='GRAFICA' AND qb.difficulty='muy alta'
      AND qb.validation_version>=6 AND ${SRS96_ELIGIBLE_SQL}
      AND ($2::boolean=FALSE OR (${FRESH111_SQL}))
    ORDER BY ci.times_asked ASC,qb.times_shown ASC,qb.id ASC LIMIT 120`,
    [topicId,Boolean(freshOnly)]);
  return rows.rows;
}




/* T43-AUD-187: solo corrección de cobertura de TEMA 43, basada en CEIS 420–439.
   No se reindexa, ni se toca T41/T42, ni se alteran preguntas/SRS existentes. */
const T43_AUDIT_187_ATOMS=[{"key":"T43-AUD-0001","section":"Historia ferroviaria","concept":"Número de vagones arrastrados en la locomotora de Richard Treveitch de 1804: cinco vagones, con 10 toneladas de acero y 70 hombres","source_page":4,"manual_page":"420","source_evidence":"El origen del sistema ferroviario se encuentra en 1804 en el sur de Gales, cuando el ingeniero de minas Richard Treveitch modificó una máquina de vapor para que moviera una locomotora a 8 km/h y arrastrara cinco vagones cargados con 10 toneladas de acero y 70 hombres. Se desplazó sobre una vía de 15 km de longitud."},{"key":"T43-AUD-0002","section":"Historia ferroviaria","concept":"Personas transportadas por la locomotora de Richard Treveitch en 1804 según el manual: 70 hombres","source_page":4,"manual_page":"420","source_evidence":"El origen del sistema ferroviario se encuentra en 1804 en el sur de Gales, cuando el ingeniero de minas Richard Treveitch modificó una máquina de vapor para que moviera una locomotora a 8 km/h y arrastrara cinco vagones cargados con 10 toneladas de acero y 70 hombres. Se desplazó sobre una vía de 15 km de longitud."},{"key":"T43-AUD-0003","section":"Historia ferroviaria","concept":"Capacidad ilustrativa de las locomotoras eléctricas citadas en el CEIS: más de 400 personas en vías de 25 kV","source_page":4,"manual_page":"420","source_evidence":"actualmente en España hay locomotoras eléctricas que alcanzan los 350 km/h y que transportan a más de 400 personas en vías electrificadas con 25 kV."},{"key":"T43-AUD-0004","section":"Subestaciones y alimentación eléctrica","concept":"Límite inferior del intervalo de tensión de las suministradoras que transforman las subestaciones: 30.000 voltios (intervalo 30.000–40.000 V)","source_page":7,"manual_page":"423","source_evidence":"Las subestaciones se encargan de transformar (y, en muchas ocasiones, de rectificar) la corriente de las suministradoras (que alcanza los 30.000-40.000 voltios)."},{"key":"T43-AUD-0005","section":"Material rodante / locomotoras","concept":"Porcentaje aproximado de líneas ferroviarias españolas que empleaban energía eléctrica en la edición CEIS: 52 %","source_page":9,"manual_page":"425","source_evidence":"Actualmente en España, más de la mitad de las líneas ferroviarias (alrededor del 52%) emplean energía eléctrica."},{"key":"T43-AUD-0006","section":"Tubería de depósitos principales (TDP)","concept":"Presión mínima del intervalo de la TDP: 7 kg/cm², con intervalo de mantenimiento de 7–10 kg/cm²","source_page":11,"manual_page":"427","source_evidence":"Los vagones de mercancías no suelen disponer de esta tubería. La presión se mantiene entre 7-10 kg/cm²."},{"key":"T43-AUD-0007","section":"Elementos de seguridad / normativa en el manual","concept":"Número aproximado de trenes que circulaban por España al día según CEIS: unos 4.000","source_page":12,"manual_page":"428","source_evidence":"Todos los trenes que circulan en España (unos 4.000 al día) tienen que cumplir la normativa específica: Especificaciones Técnicas de Interoperabilidad (ETI) y Especificaciones Técnicas de Homologación (ETH)."},{"key":"T43-AUD-0008","section":"Elementos de seguridad / ventanas de socorro","concept":"Número mínimo de ventanas de socorro por coche de viajeros: dos, señalizadas interior y exteriormente","source_page":12,"manual_page":"428","source_evidence":"Cada coche de viajeros posee, como mínimo, dos ventanas de socorro en la zona de los viajeros."},{"key":"T43-AUD-0009","section":"Red ferroviaria y entidades gestoras (edición 2015)","concept":"Kilómetros de vías administrados por Adif según el texto CEIS: 13.945 km","source_page":14,"manual_page":"430","source_evidence":"Actualmente administra 13.945 kilómetros de vías y 1.566 estaciones."},{"key":"T43-AUD-0010","section":"Red ferroviaria y entidades gestoras (edición 2015)","concept":"Número de estaciones administradas por Adif según el texto CEIS: 1.566","source_page":14,"manual_page":"430","source_evidence":"Actualmente administra 13.945 kilómetros de vías y 1.566 estaciones."},{"key":"T43-AUD-0011","section":"Sistemas de electrificación ferroviaria","concept":"Frecuencia de la red de alta velocidad española indicada por el CEIS: 50 hertzios para 25.000 V en alterna","source_page":14,"manual_page":"430","source_evidence":"Existen líneas de 3.000 voltios en continua (la red convencional), líneas de 25.000 voltios en alterna a 50 Hertzios (la red de alta velocidad) y líneas de 1.500 voltios en continua, que es la red de ancho métrico."},{"key":"T43-AUD-0012","section":"Sistemas de seguridad eléctrica","concept":"Referencia inferior de intensidad para el arranque de una unidad de Cercanías según CEIS: más de 300 o 400 amperios","source_page":19,"manual_page":"435","source_evidence":"Téngase en cuenta que una unidad de Cercanías puede necesitar para arrancar más de 300 o 400 amperios"},{"key":"T43-AUD-0013","section":"Sistemas de seguridad eléctrica","concept":"Relación comparativa indicada en el CEIS entre diferencial doméstico de 30 mA y tendido ferroviario: 10.000 veces inferior","source_page":19,"manual_page":"435","source_evidence":"los diferenciales de los domicilios saltan con una derivación de tan solo 30 mA (miliamperios), corriente capaz de matar a una persona y 10.000 veces inferior a la que circula por un tendido ferroviario)"},{"key":"T43-AUD-0014","section":"Acceso al tren / acristalamiento","concept":"Límite inferior del grosor de cristales de acceso: 5 mm, intervalo CEIS 5–9,52 mm","source_page":22,"manual_page":"438","source_evidence":"Su grosor puede oscilar entre los 5 y los 9,52 mm."},{"key":"T43-AUD-0015","section":"Materiales de fabricación / revestimiento","concept":"Límite inferior del grosor de la capa interior de extrusión: 40 mm, intervalo CEIS 40–50 mm","source_page":22,"manual_page":"438","source_evidence":"En el interior va una capa de extrusión de unos 40-50 mm y dos paredes de 3 mm con hueco en medio."},{"key":"T43-AUD-0016","section":"Técnicas de abordaje / apertura improvisada de huecos","concept":"Finalidad del primer acceso mediante una abertura reducida: comprobar funciones vitales de los accidentados y valorar el estado interior del tren","source_page":23,"manual_page":"439","source_evidence":"Para el primer acceso es suficiente realizar aberturas que permitan comprobar las funciones vitales de accidentados y valorar el estado del interior del tren."}];
async function t43AuditRepair187(topic){
  if(!t43Topic(topic))return {skipped:true};
  const data=t43LoadData();
  if(!data)return {skipped:true,missingModule:true};
  const client=await db.connect();
  try{
    await client.query('BEGIN');
    const res=await client.query('SELECT * FROM topics WHERE id=$1 FOR UPDATE',[topic.id]);
    const t=res.rows[0];
    if(!t||!t43Topic(t)||!t.file_search_indexed)
      throw Error('T43-AUD-187: tema indexado incompatible');
    // La copia local y su SHA (comprobados debajo) prevalecen sobre el nombre.
    const stored=await client.query(`SELECT trim(pdf_sha256) AS sha,
      page_count, encode(sha256(pdf_bytes),'hex') AS actual_sha
      FROM topic_local_pdfs WHERE topic_id=$1`,[t.id]);
    const file=stored.rows[0];
    if(!file||file.sha!==data.pdf_sha256||file.actual_sha!==data.pdf_sha256||
       Number(file.page_count)!==24)
      throw Error('T43-AUD-187: el PDF local no coincide con el CEIS de 24 páginas');
    const cnt=await client.query(`SELECT COUNT(*)::int AS n FROM question_bank qb
      JOIN coverage_items ci ON ci.id=qb.coverage_item_id
      WHERE ci.topic_id=$1 AND ci.item_type='grafica_t43_original'
        AND qb.active=TRUE AND qb.question_family='GRAFICA'`,[t.id]);
    if(Number(cnt.rows[0]?.n)!==86)
      throw Error('T43-AUD-187: banco gráfico incompleto; no se modifica la cobertura');
    let inserted=0;
    for(const a of T43_AUDIT_187_ATOMS){
      if(!/^T43-AUD-\d{4}$/.test(a.key)||a.source_page+416!==Number(a.manual_page)||
         !a.source_evidence||!a.concept||a.source_evidence.length<45)
        throw Error('T43-AUD-187: ficha sin cita válida '+a.key);
      const result=await client.query(`INSERT INTO coverage_items(topic_id,section,concept,
        item_type,evaluation_type,source_page,manual_page,source_evidence,exam_relevant)
        VALUES($1,$2,$3,'dato_t43_preparado','literal_documental',$4,$5,$6,TRUE)
        ON CONFLICT(topic_id,concept,item_type,evaluation_type) DO NOTHING`,
        [t.id,a.section,a.key+' · '+a.concept,a.source_page,a.manual_page,a.source_evidence]);
      inserted+=Number(result.rowCount||0);
    }
    // Los cuatro registros de la tabla de gestores fueron generados con una
    // anotación editorial en source_evidence. Limpiar SOLO esa coletilla;
    // no se cambia la entidad, el valor documental ni la procedencia del dato.
    const cleaned=await client.query(`UPDATE coverage_items
      SET source_evidence=replace(source_evidence,
        ' (DATOS DEL MANUAL EDICIÓN 2015; NO AFIRMAR VIGENCIA ACTUAL)','')
      WHERE topic_id=$1 AND item_type='dato_t43_preparado'
        AND concept LIKE 'T43-TAB-%'
        AND source_evidence LIKE '%(DATOS DEL MANUAL EDICIÓN 2015; NO AFIRMAR VIGENCIA ACTUAL)%'`,[t.id]);
    const count=await client.query(`SELECT COUNT(*)::int AS n
      FROM coverage_items WHERE topic_id=$1 AND exam_relevant=TRUE`,[t.id]);
    const total=Number(count.rows[0]?.n||0);
    await client.query('UPDATE topics SET total_items=$2 WHERE id=$1',[t.id,total]);
    await client.query('COMMIT');
    console.log('T43_AUDITORIA_187_APLICADA',JSON.stringify({topicId:t.id,inserted,total,
      cleanedEvidence:Number(cleaned.rowCount||0)}));
    return {ok:true,topicId:t.id,inserted,total,cleanedEvidence:Number(cleaned.rowCount||0)};
  }catch(err){await client.query('ROLLBACK');throw err;}
  finally{client.release();}
}

/* T44: módulo documental/gráfico aislado, sin modificación de otros temas. */
/* TEMA 44: SOLO importación documental/gráfica idempotente. Sin tocar otros temas. */
let t44PreparedData=null;
function t44Topic(topic){
  const name=String(topic?.name||topic?.topic_name||'').normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'').replace(/[_-]+/g,' ');
  // T44-188: admitir solamente el titulo CEIS definitivo o el titulo
  // de la primera indexacion originado por el nombre de descarga verificado.
  const nombreOficial=/^\s*tema\s*44\b[.\s]*rescate\s+en\s+ascensores\s*$/i.test(name);
  const nombreImportado=/^\s*tema\s*44\b[.\s]*ascensores\s+para\s+indexar\s*$/i.test(name);
  return (nombreOficial||nombreImportado) &&
    String(topic?.block||topic?.topic_block||'').toLowerCase()==='especifico';
}
function t44LoadData(){
  if(t44PreparedData)return t44PreparedData;
  const file=path.join(process.cwd(),'t44_graphics_data.js');
  if(!fs.existsSync(file))return null;
  const content=fs.readFileSync(file,'utf8');
  const marker='module.exports = ';
  const start=content.indexOf(marker);
  if(start<0)throw Error('T44: cabecera de paquete grafico invalida');
  const data=JSON.parse(content.slice(start+marker.length).trim().replace(/;\s*$/,''));
  if(data?.schema!==1||data.topic_number!==44||data.pdf_page_count!==14||
     !Array.isArray(data.images)||data.images.length!==26||
     !Array.isArray(data.questions)||data.questions.length!==73||
     new Set(data.images.map(x=>x.file)).size!==26||
     new Set(data.questions.map(x=>x.external_key)).size!==73)
    throw Error('T44: recortes o preguntas incompletos o repetidos');
  t44PreparedData=data;return data;
}
function t44WriteImages(){
  const data=t44LoadData();if(!data)return {skipped:true};
  const dir=path.join(process.cwd(),'public','graphics','ascensores');
  fs.mkdirSync(dir,{recursive:true});let written=0;
  for(const asset of data.images){
    if(!/^T44_FIG_\d{2}_P\d{3}\.png$/.test(asset.file))
      throw Error('T44: nombre de imagen inesperado');
    const buf=Buffer.from(asset.base64,'base64');
    const sha=createHash('sha256').update(buf).digest('hex');
    if(sha!==asset.sha256||!buf.subarray(0,8)
      .equals(Buffer.from([137,80,78,71,13,10,26,10])))
      throw Error('T44: checksum/png invalido '+asset.file);
    const dest=path.join(dir,asset.file);
    if(fs.existsSync(dest)){
      if(createHash('sha256').update(fs.readFileSync(dest)).digest('hex')!==sha)
        throw Error('T44: fichero de imagen existente distinto '+asset.file);
    }else{fs.writeFileSync(dest,buf);written++;}
  }
  return {images:26,written};
}
async function t44ImportOnce(topic,uploadedPdfPath=null){
  if(!t44Topic(topic))return {skipped:true};
  const data=t44LoadData();if(!data)return {skipped:true,missing:true};
  t44WriteImages();
  const client=await db.connect();
  try{
    await client.query('BEGIN');
    const topics=await client.query('SELECT * FROM topics WHERE id=$1 FOR UPDATE',[topic.id]);
    const t=topics.rows[0];
    // Importación solo cuando la fuente de la indexación coincide.
    // Si se llama desde el formulario, verificar el SHA del PDF subido.
    // Al reintentar en el arranque, exigir el nombre del PDF oficial suministrado.
    if(uploadedPdfPath){
      const uploaded=fs.readFileSync(uploadedPdfPath);
      if(createHash('sha256').update(uploaded).digest('hex')!==data.pdf_sha256)
        throw Error('T44: SHA del PDF realmente indexado distinto del paquete');
    }else{
      // T44-188: se acepta el nombre de archivo de la ultima descarga
      // UNICAMENTE si su SHA coincide con el PDF original del modulo.
      // No aceptar nombres genericos ni relajar la comprobacion de integridad.
      const originalName=String(t.source_file||'')===String(data.pdf_filename);
      const downloadAlias=String(t.source_file||'')==='TEMA44_ASCENSORES_PARA_INDEXAR.pdf' &&
        String(data.pdf_sha256)==='ecdfe969192d95deb93e3e6fa53c1ef9d841146aabe71e6d26fac14892012d8b';
      if(!originalName&&!downloadAlias)
        throw Error('T44: fuente del tema no coincide con el PDF preparado');
    }
    // T44-179: conservar la indexación File Search existente. Su PDF no se
    // guardaba localmente, pero el banco fijo de imágenes exigía ese registro.
    // El PDF exacto (14 páginas) se incorpora en el paquete con SHA verificado.
    if(!t44Topic(t)||Number(t.total_items)<1||!t.file_search_indexed)
      throw Error('T44: tema no indexado; no se altera ninguna cobertura');
    const remote=await client.query(`SELECT document_name
      FROM topic_source_documents WHERE topic_id=$1`,[t.id]);
    if(!remote.rows[0]?.document_name)
      throw Error('T44: no hay fuente File Search vinculada; no se suplanta');
    if(!data.pdf_base64||!Array.isArray(data.coverage_additions))
      throw Error('T44: falta el PDF original y el inventario de ampliaciones');
    const pdfBytes=Buffer.from(data.pdf_base64,'base64');
    const fileHash=createHash('sha256').update(pdfBytes).digest('hex');
    if(fileHash!==data.pdf_sha256||pdfBytes.length<1000||
       pdfBytes.length>20*1024*1024||
       pdfBytes.subarray(0,5).toString('latin1')!=='%PDF-')
      throw Error('T44: PDF local distinto del original indexado');
    const source=await PDFDocument.load(pdfBytes,{updateMetadata:false});
    if(source.getPageCount()!==14)throw Error('T44: el PDF no tiene 14 páginas');
    await client.query(`INSERT INTO topic_local_pdfs
      (topic_id,pdf_sha256,page_count,size_bytes,pdf_bytes)
      VALUES($1,$2,14,$3,$4) ON CONFLICT(topic_id) DO NOTHING`,
      [t.id,fileHash,pdfBytes.length,pdfBytes]);
    const stored=await client.query(`SELECT TRIM(pdf_sha256) AS sha,
      page_count,size_bytes,OCTET_LENGTH(pdf_bytes) AS stored_size,
      encode(sha256(pdf_bytes),'hex') AS stored_sha
      FROM topic_local_pdfs WHERE topic_id=$1`,[t.id]);
    const check=stored.rows[0];
    if(!check||check.sha!==fileHash||check.stored_sha!==fileHash||
       Number(check.page_count)!==14||
       Number(check.size_bytes)!==pdfBytes.length||
       Number(check.stored_size)!==pdfBytes.length)
      throw Error('T44: copia PDF local incompatible; no se sobrescribe');
    // Completar únicamente lagunas verificadas contra páginas físicas.
    // DO NOTHING preserva historial y SRS si ya se instaló antes.
    for(const item of data.coverage_additions){
      if(!/^T44-NUM-\d{4}$/.test(item.external_key)||
         !Number.isInteger(item.source_page)||item.source_page<1||item.source_page>14||
         !item.concept||!item.source_evidence)
        throw Error('T44: ampliación documental no válida');
      await client.query(`INSERT INTO coverage_items(topic_id,section,concept,
        item_type,evaluation_type,source_page,manual_page,source_evidence,exam_relevant)
        VALUES($1,$2,$3,'dato_t44_preparado','literal_documental',$4,$5,$6,TRUE)
        ON CONFLICT(topic_id,concept,item_type,evaluation_type) DO NOTHING`,
        [t.id,item.section,item.external_key+' · '+item.concept,
         item.source_page,item.manual_page,item.source_evidence]);
    }
    const imgMap=new Map();
    for(const asset of data.images){
      const file=asset.file,uri='/graphics/ascensores/'+file;
      const sourceId='ascensores/'+file;
      const q=await client.query(`INSERT INTO graphic_assets(
        source_id,topic_folder,source_file,public_url,asset_index,asset_type,
        concept,description,source_evidence,crop_x,crop_y,crop_width,crop_height,
        mask_regions,is_official_reference,is_usable,analysis_status,sanitization_version)
        VALUES($1,'ascensores',$2,$3,0,'individual',$4,$5,$6,
        0,0,1,1,'[]'::jsonb,FALSE,TRUE,'analyzed',2)
        ON CONFLICT(source_id,asset_index) DO UPDATE SET
        concept=EXCLUDED.concept,description=EXCLUDED.description,
        source_evidence=EXCLUDED.source_evidence,public_url=EXCLUDED.public_url,
        crop_x=0,crop_y=0,crop_width=1,crop_height=1,
        mask_regions='[]'::jsonb,is_usable=TRUE,analysis_status='analyzed',
        sanitization_version=2,updated_at=NOW() RETURNING id`,
      [sourceId,file,uri,'T44 figura '+asset.figure,
       'Recorte original delimitado al contenido gráfico CEIS pag. '+asset.printed_page,
       'CEIS Guadalajara, Parte 4, pag. '+asset.printed_page]);
      imgMap.set(file,{id:Number(q.rows[0].id),uri,sourceId});
    }
    let imported=0;
    for(const row of data.questions){
      const img=imgMap.get(row.graphic_file);
      if(!img||row.image_sha256!==data.images.find(i=>i.file===row.graphic_file)?.sha256||
         !/^T44-GRAF-\d{4}$/.test(row.external_key)||
         !Array.isArray(row.options)||row.options.length!==4||
         new Set(row.options).size!==4||
         !Number.isInteger(row.correct_index)||row.correct_index<0||row.correct_index>3||
         row.question_family!=='GRAFICA'||row.difficulty!=='muy alta'||
         !row.stem||!row.source_evidence)
        throw Error('T44: pregunta no valida '+row.external_key);
      const key=row.external_key+' · '+row.coverage_concept;
      const c=await client.query(`INSERT INTO coverage_items(topic_id,section,concept,
        item_type,evaluation_type,source_page,manual_page,source_evidence,exam_relevant)
        VALUES($1,$2,$3,'grafica_t44_original','interpretacion_visual',$4,$5,$6,TRUE)
        ON CONFLICT(topic_id,concept,item_type,evaluation_type) DO UPDATE SET
        section=EXCLUDED.section,source_page=EXCLUDED.source_page,
        manual_page=EXCLUDED.manual_page,source_evidence=EXCLUDED.source_evidence,
        exam_relevant=TRUE RETURNING id`,
      [t.id,row.coverage_section,key,row.source_pdf_page,row.manual_page,row.source_evidence]);
      const coverageId=Number(c.rows[0].id);
      const graphic={...row.graphic,assetId:img.id,publicUrl:img.uri,
        sourceId:img.sourceId,assetType:'individual',
        crop:{x:0,y:0,width:1,height:1},maskRegions:[]};
      const previous=await client.query(`SELECT id,stem,options,correct_index FROM question_bank
        WHERE coverage_item_id=$1 AND question_family='GRAFICA' ORDER BY id DESC
        LIMIT 1 FOR UPDATE`,[coverageId]);
      if(previous.rows.length){
        const old=previous.rows[0];
        if(old.stem!==row.stem||JSON.stringify(old.options)!==JSON.stringify(row.options)||
          Number(old.correct_index)!==Number(row.correct_index))
          throw Error('T44: pregunta distinta ya existente: '+row.external_key);
        await client.query(`UPDATE question_bank SET active=TRUE,graphic=$2::jsonb,
          updated_at=NOW() WHERE id=$1`,[old.id,JSON.stringify(graphic)]);
      }else await client.query(`INSERT INTO question_bank(coverage_item_id,stem,options,
        correct_index,explanation,source_evidence,source_page,manual_page,
        question_family,difficulty,graphic,validation_version,active)
        VALUES($1,$2,$3::jsonb,$4,$5,$6,$7,$8,'GRAFICA','muy alta',$9::jsonb,6,TRUE)`,
        [coverageId,row.stem,JSON.stringify(row.options),row.correct_index,
        row.explanation,row.source_evidence,row.source_pdf_page,row.manual_page,
        JSON.stringify(graphic)]);
      imported++;
    }
    if(imported!==73)throw Error('T44: numero de preguntas importadas incompleto');
    await client.query(`UPDATE graphic_assets SET is_usable=FALSE,updated_at=NOW()
      WHERE topic_folder='ascensores' AND source_file LIKE 'Screenshot_%'
      AND is_usable=TRUE`);
    await client.query(`UPDATE topics SET
      name='TEMA 44. RESCATE EN ASCENSORES',
      total_items=(SELECT COUNT(*) FROM coverage_items
        WHERE topic_id=$1 AND exam_relevant=TRUE) WHERE id=$1`,[t.id]);
    await client.query('COMMIT');
    console.log('T44_GRAFICOS_CARGADOS',JSON.stringify({topicId:t.id,
      images:26,questions:73,documentaryAdditions:data.coverage_additions.length,
      pdfSha256:fileHash}));
    return {ok:true,topicId:t.id,images:26,questions:73,
      documentaryAdditions:data.coverage_additions.length};
  }catch(e){await client.query('ROLLBACK');throw e;}
  finally{client.release();}
}
async function t44GraphicBankPairs(topicId,freshOnly,difficulty){
  if(difficulty!=='muy alta')return [];
  const rows=await db.query(`SELECT qb.id AS question_id,qb.stem,qb.options,
      qb.correct_index,qb.explanation,qb.source_evidence,qb.source_page,
      qb.manual_page,qb.question_family,qb.difficulty,qb.graphic,qb.validation_version,
      ci.id AS coverage_id,ci.topic_id,ci.section,ci.concept,ci.item_type,
      ci.evaluation_type,ci.source_evidence AS ci_evidence,ci.source_page AS ci_page,
      ci.manual_page AS ci_manual,t.name AS topic_name,t.block AS topic_block
    FROM question_bank qb JOIN coverage_items ci ON ci.id=qb.coverage_item_id
    JOIN topics t ON t.id=ci.topic_id
    LEFT JOIN coverage_review_state crs ON crs.coverage_item_id=ci.id
    WHERE ci.topic_id=$1 AND ci.item_type='grafica_t44_original'
      AND ci.exam_relevant=TRUE AND qb.active=TRUE
      AND qb.question_family='GRAFICA' AND qb.difficulty='muy alta'
      AND qb.validation_version>=6 AND ${SRS96_ELIGIBLE_SQL}
      AND ($2::boolean=FALSE OR (${FRESH111_SQL}))
    ORDER BY ci.times_asked ASC,qb.times_shown ASC,qb.id ASC LIMIT 120`,
    [topicId,Boolean(freshOnly)]);
  return rows.rows;
}





/* T45: módulo documental/gráfico aislado, sin modificación de otros temas. */
/* TEMA 45: SOLO importación documental/gráfica idempotente. Sin tocar otros temas. */
let t45PreparedData=null;
function t45Topic(topic){
  const name=String(topic?.name||topic?.topic_name||'').normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'').replace(/[_-]+/g,' ')
    .replace(/\s+/g,' ').trim();
  return /^tema\s*45\b/i.test(name) &&
    /(?:apicola|otras especies)/i.test(name) &&
    String(topic?.block||topic?.topic_block||'').toLowerCase()==='especifico';
}
function t45LoadData(){
  if(t45PreparedData)return t45PreparedData;
  const file=path.join(process.cwd(),'t45_graphics_data.js');
  if(!fs.existsSync(file))return null;
  const content=fs.readFileSync(file,'utf8');
  const marker='module.exports = ';
  const start=content.indexOf(marker);
  if(start<0)throw Error('T45: cabecera de paquete grafico invalida');
  const data=JSON.parse(content.slice(start+marker.length).trim().replace(/;\s*$/,''));
  if(data?.schema!==1||data.topic_number!==45||data.pdf_page_count!==32||
     !Array.isArray(data.images)||data.images.length!==20||
     !Array.isArray(data.questions)||data.questions.length!==54||
     new Set(data.images.map(x=>x.file)).size!==20||
     new Set(data.questions.map(x=>x.external_key)).size!==54)
    throw Error('T45: recortes o preguntas incompletos o repetidos');
  t45PreparedData=data;return data;
}
function t45WriteImages(){
  const data=t45LoadData();if(!data)return {skipped:true};
  const dir=path.join(process.cwd(),'public','graphics','apicola');
  fs.mkdirSync(dir,{recursive:true});let written=0;
  for(const asset of data.images){
    if(!/^T45_FIG_\d{2}_P\d{3}\.png$/.test(asset.file))
      throw Error('T45: nombre de imagen inesperado');
    const buf=Buffer.from(asset.base64,'base64');
    const sha=createHash('sha256').update(buf).digest('hex');
    if(sha!==asset.sha256||!buf.subarray(0,8)
      .equals(Buffer.from([137,80,78,71,13,10,26,10])))
      throw Error('T45: checksum/png invalido '+asset.file);
    const dest=path.join(dir,asset.file);
    if(fs.existsSync(dest)){
      if(createHash('sha256').update(fs.readFileSync(dest)).digest('hex')!==sha)
        throw Error('T45: fichero de imagen existente distinto '+asset.file);
    }else{fs.writeFileSync(dest,buf);written++;}
  }
  return {images:20,written};
}
async function t45ImportOnce(topic,uploadedPdfPath=null){
  if(!t45Topic(topic))return {skipped:true};
  const data=t45LoadData();if(!data)return {skipped:true,missing:true};
  t45WriteImages();
  const client=await db.connect();
  try{
    await client.query('BEGIN');
    const topics=await client.query('SELECT * FROM topics WHERE id=$1 FOR UPDATE',[topic.id]);
    const t=topics.rows[0];
    // Importación solo cuando la fuente de la indexación coincide.
    // Si se llama desde el formulario, verificar el SHA del PDF subido.
    // Al reintentar en el arranque, exigir el nombre del PDF oficial suministrado.
    if(uploadedPdfPath){
      const uploaded=fs.readFileSync(uploadedPdfPath);
      const hashUploaded=createHash('sha256').update(uploaded).digest('hex');
      if(hashUploaded!==data.pdf_sha256 &&
        !(Array.isArray(data.pdf_equivalent_sha256)&&
          data.pdf_equivalent_sha256.includes(hashUploaded)))
        throw Error('T45: SHA del PDF realmente indexado distinto del paquete');
    }else{
      // Retoma el tema solo si el PDF que figura como fuente es el PDF
      // realmente suministrado. No deducir identidades desde un titulo.
      const known=String(t.source_file||'')===String(data.pdf_filename);
      if(!known){
        const prior=await client.query('SELECT TRIM(pdf_sha256) AS sha FROM topic_local_pdfs WHERE topic_id=$1',[t.id]);
        if(prior.rows[0]?.sha!==String(data.pdf_sha256))
          throw Error('T45: fuente distinta del PDF CEIS preparado');
      }
    }
    // T45-179: conservar la indexación File Search existente. Su PDF no se
    // guardaba localmente, pero el banco fijo de imágenes exigía ese registro.
    // El PDF exacto (32 páginas) se incorpora en el paquete con SHA verificado.
    if(!t45Topic(t)||Number(t.total_items)<1)
      throw Error('T45: tema sin cobertura; no se altera ninguna ficha');
    // SERVER190: admitir también el PDF local original con SHA verificado.
    // Solo se permite para T45; los demás temas y File Search no cambian.
    const remote=await client.query(`SELECT document_name
      FROM topic_source_documents WHERE topic_id=$1`,[t.id]);
    const local=await client.query(`SELECT TRIM(pdf_sha256) AS sha,
      page_count,size_bytes,OCTET_LENGTH(pdf_bytes) AS stored_size,
      ENCODE(SHA256(pdf_bytes),'hex') AS actual_sha
      FROM topic_local_pdfs WHERE topic_id=$1`,[t.id]);
    const loc=local.rows[0];
    const localReady=Boolean(loc && loc.sha===data.pdf_sha256 &&
      loc.actual_sha===data.pdf_sha256 && Number(loc.page_count)===32 &&
      Number(loc.size_bytes)===Number(loc.stored_size) &&
      remote.rows[0]?.document_name==='local-pdf:sha256:'+data.pdf_sha256);
    const remoteReady=Boolean(t.file_search_indexed &&
      remote.rows[0]?.document_name &&
      !String(remote.rows[0].document_name).startsWith('local-pdf:'));
    if(!localReady && !remoteReady)
      throw Error('T45: falta indexación o PDF local íntegro; se conserva la cobertura');
    if(!data.pdf_base64||!Array.isArray(data.coverage_additions))
      throw Error('T45: falta el PDF original y el inventario de ampliaciones');
    const pdfBytes=Buffer.from(data.pdf_base64,'base64');
    const fileHash=createHash('sha256').update(pdfBytes).digest('hex');
    if(fileHash!==data.pdf_sha256||pdfBytes.length<1000||
       pdfBytes.length>20*1024*1024||
       pdfBytes.subarray(0,5).toString('latin1')!=='%PDF-')
      throw Error('T45: PDF local distinto del original indexado');
    const source=await PDFDocument.load(pdfBytes,{updateMetadata:false});
    if(source.getPageCount()!==32)throw Error('T45: el PDF no tiene 32 páginas');
    await client.query(`INSERT INTO topic_local_pdfs
      (topic_id,pdf_sha256,page_count,size_bytes,pdf_bytes)
      VALUES($1,$2,32,$3,$4) ON CONFLICT(topic_id) DO NOTHING`,
      [t.id,fileHash,pdfBytes.length,pdfBytes]);
    const stored=await client.query(`SELECT TRIM(pdf_sha256) AS sha,
      page_count,size_bytes,OCTET_LENGTH(pdf_bytes) AS stored_size,
      encode(sha256(pdf_bytes),'hex') AS stored_sha
      FROM topic_local_pdfs WHERE topic_id=$1`,[t.id]);
    const check=stored.rows[0];
    if(!check||check.sha!==fileHash||check.stored_sha!==fileHash||
       Number(check.page_count)!==32||
       Number(check.size_bytes)!==pdfBytes.length||
       Number(check.stored_size)!==pdfBytes.length)
      throw Error('T45: copia PDF local incompatible; no se sobrescribe');
    // Completar únicamente lagunas verificadas contra páginas físicas.
    // DO NOTHING preserva historial y SRS si ya se instaló antes.
    for(const item of data.coverage_additions){
      if(!/^T45-NUM-\d{4}$/.test(item.external_key)||
         !Number.isInteger(item.source_page)||item.source_page<1||item.source_page>32||
         !item.concept||!item.source_evidence)
        throw Error('T45: ampliación documental no válida');
      await client.query(`INSERT INTO coverage_items(topic_id,section,concept,
        item_type,evaluation_type,source_page,manual_page,source_evidence,exam_relevant)
        VALUES($1,$2,$3,'dato_t45_preparado','literal_documental',$4,$5,$6,TRUE)
        ON CONFLICT(topic_id,concept,item_type,evaluation_type) DO NOTHING`,
        [t.id,item.section,item.external_key+' · '+item.concept,
         item.source_page,item.manual_page,item.source_evidence]);
    }
    const imgMap=new Map();
    for(const asset of data.images){
      const file=asset.file,uri='/graphics/apicola/'+file;
      const sourceId='apicola/'+file;
      const q=await client.query(`INSERT INTO graphic_assets(
        source_id,topic_folder,source_file,public_url,asset_index,asset_type,
        concept,description,source_evidence,crop_x,crop_y,crop_width,crop_height,
        mask_regions,is_official_reference,is_usable,analysis_status,sanitization_version)
        VALUES($1,'apicola',$2,$3,0,'individual',$4,$5,$6,
        0,0,1,1,'[]'::jsonb,FALSE,TRUE,'analyzed',2)
        ON CONFLICT(source_id,asset_index) DO UPDATE SET
        concept=EXCLUDED.concept,description=EXCLUDED.description,
        source_evidence=EXCLUDED.source_evidence,public_url=EXCLUDED.public_url,
        crop_x=0,crop_y=0,crop_width=1,crop_height=1,
        mask_regions='[]'::jsonb,is_usable=TRUE,analysis_status='analyzed',
        sanitization_version=2,updated_at=NOW() RETURNING id`,
      [sourceId,file,uri,'T45 figura '+asset.figure,
       'Recorte original delimitado al contenido gráfico CEIS pag. '+asset.printed_page,
       'CEIS Guadalajara, Parte 8, pag. '+asset.printed_page]);
      imgMap.set(file,{id:Number(q.rows[0].id),uri,sourceId});
    }
    let imported=0;
    for(const row of data.questions){
      const img=imgMap.get(row.graphic_file);
      if(!img||row.image_sha256!==data.images.find(i=>i.file===row.graphic_file)?.sha256||
         !/^T45-GRAF-\d{4}$/.test(row.external_key)||
         !Array.isArray(row.options)||row.options.length!==4||
         new Set(row.options).size!==4||
         !Number.isInteger(row.correct_index)||row.correct_index<0||row.correct_index>3||
         row.question_family!=='GRAFICA'||row.difficulty!=='muy alta'||
         !row.stem||!row.source_evidence)
        throw Error('T45: pregunta no valida '+row.external_key);
      const key=row.external_key+' · '+row.coverage_concept;
      const c=await client.query(`INSERT INTO coverage_items(topic_id,section,concept,
        item_type,evaluation_type,source_page,manual_page,source_evidence,exam_relevant)
        VALUES($1,$2,$3,'grafica_t45_original','interpretacion_visual',$4,$5,$6,TRUE)
        ON CONFLICT(topic_id,concept,item_type,evaluation_type) DO UPDATE SET
        section=EXCLUDED.section,source_page=EXCLUDED.source_page,
        manual_page=EXCLUDED.manual_page,source_evidence=EXCLUDED.source_evidence,
        exam_relevant=TRUE RETURNING id`,
      [t.id,row.coverage_section,key,row.source_pdf_page,row.manual_page,row.source_evidence]);
      const coverageId=Number(c.rows[0].id);
      const graphic={...row.graphic,assetId:img.id,publicUrl:img.uri,
        sourceId:img.sourceId,assetType:'individual',
        crop:{x:0,y:0,width:1,height:1},maskRegions:[]};
      const previous=await client.query(`SELECT id,stem,options,correct_index FROM question_bank
        WHERE coverage_item_id=$1 AND question_family='GRAFICA' ORDER BY id DESC
        LIMIT 1 FOR UPDATE`,[coverageId]);
      if(previous.rows.length){
        const old=previous.rows[0];
        if(old.stem!==row.stem||JSON.stringify(old.options)!==JSON.stringify(row.options)||
          Number(old.correct_index)!==Number(row.correct_index))
          throw Error('T45: pregunta distinta ya existente: '+row.external_key);
        await client.query(`UPDATE question_bank SET active=TRUE,graphic=$2::jsonb,
          updated_at=NOW() WHERE id=$1`,[old.id,JSON.stringify(graphic)]);
      }else await client.query(`INSERT INTO question_bank(coverage_item_id,stem,options,
        correct_index,explanation,source_evidence,source_page,manual_page,
        question_family,difficulty,graphic,validation_version,active)
        VALUES($1,$2,$3::jsonb,$4,$5,$6,$7,$8,'GRAFICA','muy alta',$9::jsonb,6,TRUE)`,
        [coverageId,row.stem,JSON.stringify(row.options),row.correct_index,
        row.explanation,row.source_evidence,row.source_pdf_page,row.manual_page,
        JSON.stringify(graphic)]);
      imported++;
    }
    if(imported!==54)throw Error('T45: numero de preguntas importadas incompleto');
    await client.query(`UPDATE graphic_assets SET is_usable=FALSE,updated_at=NOW()
      WHERE topic_folder='apicola' AND source_file LIKE 'Screenshot_%'
      AND is_usable=TRUE`);
    await client.query(`UPDATE topics SET
      name='TEMA 45. RESCATE APÍCOLA Y DE OTRAS ESPECIES',
      total_items=(SELECT COUNT(*) FROM coverage_items
        WHERE topic_id=$1 AND exam_relevant=TRUE) WHERE id=$1`,[t.id]);
    await client.query('COMMIT');
    console.log('T45_GRAFICOS_CARGADOS',JSON.stringify({topicId:t.id,
      images:20,questions:54,documentaryAdditions:data.coverage_additions.length,
      pdfSha256:fileHash}));
    return {ok:true,topicId:t.id,images:20,questions:54,
      documentaryAdditions:data.coverage_additions.length};
  }catch(e){await client.query('ROLLBACK');throw e;}
  finally{client.release();}
}

