// SERVER204: ejemplo ilustrativo Mattson T52 no examinable. Los datos del
// PDF permanecen; no deben ocupar plazas nuevas aunque se reimporte el tema.
function t52MattsonExample204(r){
  if(healthTopicNumber192(r)!==52)return false;
  const c=String(r?.concept||'').trim();
  return /^Valores de la Tabla 1 de prioridades de b[uú]squeda asignadas por el m[eé]todo de Mattson/i.test(c)||
    /^T52-EJ-MA-(?:0020|00(?:3[0-9]|4[0-9]|5[0-9]|6[0-2]))\b/i.test(c)||
    /^T52-GRAF-0001\b/i.test(c);
}
// SOLO equivalencia 1:25.000, no se fusionan conceptos de brújula/UTM.
function t52ScaleConcept204(r){
  if(healthTopicNumber192(r)!==52)return null;
  const c=String(r?.concept||'');
  const content=[r?.concept,r?.section,r?.source_evidence].join(' ');
  if(/br[uú]jula/i.test(c)||!/\b1\s*:\s*25[.\s]?000\b/i.test(content))return null;
  if(!/(?:escala|distancia|cent[ií]metro|equivalencia|medid[oa])/i.test(c))return null;
  return `${r.topic_id}:escala25000_distancia`;
}
// Comparación local MUY conservadora: preserva cambios numéricos, negaciones,
// condiciones, unidades, direcciones y relaciones físicas. Sin Gemini extra.
function specificEquivalentOptions204(q){
  if(!Array.isArray(q?.options)||q.options.length!==4)return false;
  const norm=x=>String(x||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
  const stop=new Set('se el la los las de del en por para con que una un unos unas como cual sus su al es son tiene tienen presenta permite obtener aportar caracteriza caracteriza entre ventajas virtud capacidad conjunto constituye refiere refiere ofrece consiste caracteriza principal referido respecto configuracion'.split(' '));
  const meaningful=x=>new Set(norm(x).split(' ').filter(w=>(w.length>2||w==='no'||w==='si')&&!stop.has(w)));
  const numbers=x=>(String(x).match(/[+-]?\d+(?:[.,]\d+)*/g)||[]).join('|');
  const protectedWords=new Set('no nunca sin excepto salvo antes despues superior inferior anterior posterior abierto abierta cerrado cerrada izquierda derecha arriba abajo mayor menor mas menos alta baja primero segundo tercero cuarto verdadero falso correcto incorrecto diferente iguales inversa directa'.split(' '));
  for(let i=0;i<4;i++)for(let j=i+1;j<4;j++){
    if(numbers(q.options[i])!==numbers(q.options[j]))continue;
    const a=meaningful(q.options[i]),b=meaningful(q.options[j]);
    // No confundir el orden de válvulas, tramos o condiciones contrapuestas.
    if([['abierta','cerrada'],['abierto','cerrado'],['antes','despues'],['mayor','menor'],['izquierda','derecha']].some(pair=>
       pair.every(w=>a.has(w)&&b.has(w))))continue;
    if(Math.min(a.size,b.size)<4)continue;
    if([...protectedWords].some(w=>a.has(w)!==b.has(w)))continue;
    const common=[...a].filter(w=>b.has(w)).length;
    if(common/Math.max(a.size,b.size)>=0.95)return true;
  }
  return false;
}
// SERVER205 — no asignar INCORRECTA a una sola frase factual.
// Tres hechos verdaderos DISTINTOS requieren evidencia para los tres; si
// sólo consta un dato breve, convertir en CORRECTA (una clave, tres errores
// próximos) preserva la evaluación sin inventar otras verdades.
function specificOneFactNegative205(t){
  if(String(t?.topic_block||'').toLowerCase()!=='especifico'||iiff91Topic(t)||
     t?.questionFamily!=='2026_INCORRECTA')return false;
  const ev=String(t?.source_evidence||'').trim();
  // Límite intencionadamente prudente: NO interpretar párrafos largos.
  if(!ev||ev.length>=135)return false;
  const clauses=ev.split(/[;\n•]/).filter(x=>x.trim().length>=15);
  return clauses.length<3;
}
// SERVER205 — control mínimo transversal de alternativas (4 opciones).
// Detecta tres alternativas con el MISMO contenido factual aunque usen verbos
// introductorios distintos. Nunca interpreta como equivalentes diferencias de
// números, unidades, negación, magnitudes, categorías, orden o direcciones.
// Complejidad fija: seis pares como máximo, sin SQL, llamadas ni reintentos nuevos.
function optionTriplicate205(q){
  if(!Array.isArray(q?.options)||q.options.length!==4)return false;
  const fold=x=>String(x??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .toLowerCase().replace(/[^a-z0-9]+/g,' ').replace(/\s+/g,' ').trim();
  const fillers=new Set(('la el los las un una unos unas de del por para con que como se es son ' +
   'en al a tiene tienen presenta permiten permite obtener obtiene aportar aporta ' +
   'aporta conlleva caracteriza caracteriza como constituye resulta ' +
   'ofrece ofrecer entre sus ventaja ventajas principal principales ' +
   'del conjunto').split(' '));
  // No se descartan diferencias físicas, normativas o de sentido de la frase.
  const critical=new Set(('no nunca sin salvo excepto ni solo solamente unicamente ' +
    'antes despues primero segundo tercero cuarto ultima ultimo mayor menor superior inferior ' +
    'alta baja alto bajo izquierda derecha delante detras siempre puede debe ' +
    'abierta abierto cerrada cerrado positivo negativo ascenso descenso ' +
    'publica privada longitudinal transversal ' +
    'mas menos cada simultaneamente alternativamente junto separado').split(' '));
  const signatures=q.options.map(v=>{
    const normalized=fold(v),words=normalized.split(' ').filter(Boolean);
    const numbers=(String(v).match(/[+-]?\d+(?:[.,]\d+)*/g)||[]).join('|');
    // El ORDEN también forma parte de la relación: 'nieve antes que lluvia'
    // no equivale a 'lluvia antes que nieve'. No ordenar calificadores.
    const qualifiers=words.filter(w=>critical.has(w)).join('|');
    // Preservar orden y multiplicidad de palabras técnicas relevantes.
    // Sinonimias de introducción se resuelven con 'fillers', no por similitud
    // estadística que confunde un cambio de régimen, objeto o relación.
    const meaningful=words.filter(w=>!fillers.has(w)&&!critical.has(w));
    return {numbers,qualifiers,meaningful};
  });
  const matched=(a,b)=>{
    if(a.numbers!==b.numbers||a.qualifiers!==b.qualifiers||
       a.meaningful.length<3||b.meaningful.length<3)return false;
    // Tres paráfrasis con el MISMO contenido sí se rechazan; permutar
    // 'máximo relativo' y 'máximo absoluto' NO es una repetición.
    return a.meaningful.join('\u001f')===b.meaningful.join('\u001f');
  };
  for(let i=0;i<4;i++)for(let j=i+1;j<4;j++)for(let k=j+1;k<4;k++){
    if(matched(signatures[i],signatures[j])&&
       matched(signatures[i],signatures[k])&&
       matched(signatures[j],signatures[k]))return true;
  }
  return false;
}
function specificQualityIssue204(q,t,difficulty){
  return difficulty==='muy alta' && String(t?.topic_block||'').toLowerCase()==='especifico' &&
    !iiff91Topic(t) && specificEquivalentOptions204(q)?'alternativas_parafraseadas':null;
}

// SERVER203: Dos exportaciones byte-distintas del MISMO PDF T54, comprobadas
// página a página (38/38: texto y render idénticos). Nunca aceptar otros PDF.
const HEALTH_T54_EQUIVALENT_SHA203='3deffdfbf88aefa5bd014ad3fa35baaf6ed3be28f4b673c4775fe632552eacf4';
function healthPdfApproved203(n,sha,data){
  return sha===data.pdf_sha256 ||
    (n===54 && data.pdf_sha256==='06a0768038f7c1dd1979579d39dfbb9e1e12f310eed4eff2c3824076d5e58cb6' &&
     sha===HEALTH_T54_EQUIVALENT_SHA203);
}
const healthCache192=new Map();
function healthTopicNumber192(topic){
  if(String(topic?.block||topic?.topic_block||'').trim().toLowerCase()!=='especifico')return 0;
  const name=String(topic?.name||topic?.topic_name||'').normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'').replace(/[_-]/g,' ').replace(/\s+/g,' ').trim().toUpperCase();
  const m=name.match(/^TEMA\s*(4[6-9]|5[0-5])\b/);
  if(!m)return 0;
  const n=Number(m[1]);
  return HEALTH_ALIAS_192[n]?.test(name)?n:0;
}
function healthLoadData192(n){
  if(healthCache192.has(n))return healthCache192.get(n);
  if(!HEALTH_NAMES_192[n])return null;
  const file=path.join(process.cwd(), n===51?'t51_aperturas_data.js':n===52?'t52_busqueda_areas_data.js':n===53?'t53_rios_inundaciones_data.js':n===54?'t54_vehiculos_data.js':n===55?'t55_industriales_data.js':`t${n}_health_data.js`);
  if(!fs.existsSync(file))return null;
  const source=fs.readFileSync(file,'utf8').trim();
  const prefix='module.exports = ';
  if(!source.startsWith(prefix)||!source.endsWith(';'))
    throw Error(`HEALTH192: formato de modulo T${n} no reconocido`);
  const data=JSON.parse(source.slice(prefix.length,-1));
  if(data?.schema!==1||data.topic_number!==n||
     !Array.isArray(data.images)||!Array.isArray(data.questions)||
     !Array.isArray(data.coverage_additions)||
     (data.questions.length<data.images.length)||
     new Set(data.images.map(a=>a.file)).size!==data.images.length||
     new Set(data.questions.map(q=>q.external_key)).size!==data.questions.length||
     !/^[0-9a-f]{64}$/.test(String(data.pdf_sha256||'')) ||
     !Number.isInteger(data.pdf_page_count)||data.pdf_page_count<1)
    throw Error(`HEALTH192: modulo T${n} incompleto`);
  healthCache192.set(n,data);return data;
}
function healthWriteImages192(onlyTopic=0){
  let count=0;
  for(const n of Object.keys(HEALTH_NAMES_192).map(Number)){
    if(onlyTopic && n!==onlyTopic)continue;
    const data=healthLoadData192(n);
    if(!data)continue;
    const dir=path.join(process.cwd(),'public','graphics',n===53?'rios-inundaciones-t53':n===54?'vehiculos-t54':n===55?'incendios-industriales-t55':`salud-t${n}`);
    fs.mkdirSync(dir,{recursive:true});
    for(const a of data.images){
      if(!new RegExp(`^T${n}_FIG_\\d{2}_P\\d{3}\\.png$`).test(a.file))
        throw Error(`HEALTH192: nombre de imagen no permitido T${n}`);
      const bytes=Buffer.from(a.base64,'base64');
      const sha=createHash('sha256').update(bytes).digest('hex');
      if(sha!==a.sha256||!bytes.subarray(0,8).equals(
        Buffer.from([137,80,78,71,13,10,26,10])))
        throw Error(`HEALTH192: imagen o SHA invalido ${a.file}`);
      const dest=path.join(dir,a.file);
      if(fs.existsSync(dest)){
        if(createHash('sha256').update(fs.readFileSync(dest)).digest('hex')!==sha)
          throw Error(`HEALTH192: imagen distinta ya instalada ${a.file}`);
      }else{fs.writeFileSync(dest,bytes);count++;}
    }
  }
  return count;
}
async function healthReplaceDocument192(topic,pdfPath,items){
  const n=healthTopicNumber192(topic),data=healthLoadData192(n);
  if(!n||!data)throw Error('HEALTH192: tema o paquete sin coincidencia');
  const bytes=fs.readFileSync(pdfPath);
  const sha=createHash('sha256').update(bytes).digest('hex');
  if(!healthPdfApproved203(n,sha,data)||bytes.length<1000||bytes.length>20*1024*1024||
     bytes.subarray(0,5).toString('latin1')!=='%PDF-')
     throw Error(`HEALTH192: PDF T${n} distinto del auditado`);
  const document=await PDFDocument.load(bytes,{updateMetadata:false});
  if(document.getPageCount()!==data.pdf_page_count)
    throw Error(`HEALTH192: paginas T${n} no coinciden`);
  if(!Array.isArray(items)||items.length<1||items.some(x=>
      !Number.isInteger(x.sourcePage)||x.sourcePage<1||
      x.sourcePage>data.pdf_page_count||!x.concept||!x.sourceEvidence))
    throw Error(`HEALTH192: contenido no indexable T${n}`);
  // PDF y cobertura se confirman juntos como en T45/190. Sin File Search.
  await saveCoverageItems(topic.id,items,`local-pdf:sha256:${sha}`,
    {sha,pages:data.pdf_page_count,bytes});
  console.log(`HEALTH192_PDF_COBERTURA_LOCAL T${n} fichas=${items.length}`);
}
