function t39ModeloCompleto153(t){
  const tag=String(t39NumericModel131(t)||'').split(':')[0];
  const ids=T39_FAMILIAS_153[tag]||[];
  // Nunca convertir una teoría en cálculo por haber coincidido una palabra.
  if(!ids.length)return null;
  const available=ids.filter(id=>T39_MODELOS_153.some(m=>m.id===id));
  if(!available.length)return null;
  const selectedId=available[Math.floor(Math.random()*available.length)];
  const m=T39_MODELOS_153.find(x=>x.id===selectedId);
  const unidades={};const conversiones={};
  for(const [variable,values] of Object.entries(m.unidades_y_variaciones||{})){
    if(!Array.isArray(values)||!values.length)continue;
    const chosen=values[Math.floor(Math.random()*values.length)];
    unidades[variable]=chosen;
    const factor=T39_FACTORES_SI_153[chosen];
    if(Number.isFinite(factor))conversiones[variable]={unidad:chosen,multiplicadorHaciaSI:factor};
  }
  return {id:m.id,familia:m.familia,titulo:m.titulo,
    fuentePaginas:m.paginas_manual,relacionesDocumentadas:m.relaciones_documentadas,
    ejemplo:{enunciado:m.enunciado,opciones:m.opciones,respuesta:m.respuesta,
      resolucion:m.resolucion},unidadesPermitidas:m.unidades_y_variaciones,
    combinacionElegida:unidades,conversiones,resultadoSI:m.unidades_y_variaciones?.resultado_SI,
    restricciones:m.restricciones};
}
