    const rho=entries.filter(x=>/^kg\/m[³3]$/i.test(x.unit));
    const g=entries.filter(x=>/^m\/s[²2]$/i.test(x.unit));
    const h=entries.filter(x=>/^(?:m|cm|mm)$/i.test(x.unit));
